import { I, IN, dish } from "./catalog-kit.ts";
import type { Recipe, RecipeSource } from "./types";

const packSource: RecipeSource = {
  book: "Plant-Based Cookbook",
  author: "Trish Sebben-Krupka",
  year: 2015,
  era: "2010s",
  archiveId: "plant-based-cookbook",
  credit: "Plant-Based Cookbook (Trish Sebben-Krupka / DK Publishing). Internet Archive plant-based-cookbook. Founder-cleared free use. Ingredients from the book; method by Spoonful Kitchen.",
};

function h(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  nutrition: Recipe["nutrition"],
): Recipe {
  return dish({
    id, name, cuisine, description, minutes, protein, plate,
    tags: Array.from(new Set(["vintage", "book-plant-based", "era-2010s", ...tags])),
    ingredients, steps, nutrition, source: packSource,
  });
}

/** Kitchen RESTAGE HOLD#4 from IA plant-based-cookbook (trunc/bleed/orphan I() scrubbed vs DjVu; claim_go=false). */
export const PLANT_BASED_RECIPES: Recipe[] = [
  h("plnt-001", "Caramelized Onions", "American", ["section-book-plant-based"], "veg", "skillet", 45, "When onions are cooked slowly in just a little bit of fat, their sugars caramelize, yielding a sweet, savory, dark brown mass of delicious flavor.", [I("large yellow onions", 2, "", "Produce"), I("extra-virgin olive oil", 1, "tbsp", "Pantry"), I("kosher salt", 0.25, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices")], ["Halve and peel the yellow onions, trim off both ends, and cut them into thin 1/8-inch (3mm) half-moons.", "Warm the extra-virgin olive oil in a 12-inch (30.5cm) sauté pan set on medium-high. Tip in the onions, give them a stir, then turn the heat down to low and season with the kosher salt and black pepper.", "Let the onions cook gently for about 45 minutes, stirring roughly every 10 minutes, until soft and a deep golden brown. They should barely sizzle; lower the heat if they start to fry.", "Use right away, or chill in a sealed container for as long as 5 days."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-002", "Simple Vegetable Stock", "American", ["section-book-plant-based"], "veg", "soup", 45, "This light and flavorful vegetable stock blends well with other ingredients, making it the perfect base for any soup or sauce.", [I("large leeks, halved lengthwise, washed, and cut into 1-in. (2.5cm) chunks", 2, "", "Produce"), I("large yellow onions, root end trimmed and cut into 1-in. (2.5cm) chunks", 2, "", "Produce"), I("medium carrots, scrubbed and cut into 1-in. (2.5cm) chunks", 4, "", "Produce"), I("large stalks celery, cut into 1-in. (2.5cm) chunks", 8, "", "Produce"), I("sliced button mushrooms", 2, "cups", "Produce"), I("bay leaf", 1, "", "Herbs & Spices"), I("fresh Italian flat-leaf parsley leaves and stems", 0.5, "cups", "Produce"), I("thyme", 3, "sprigs", "Herbs & Spices"), I("whole black peppercorns", 1, "tsp", "Herbs & Spices"), I("tamari or soy sauce", 2, "tbsp", "Pantry"), I("(4L) filtered water", 4, "qt", "Pantry")], ["Put the leeks and yellow onions, the carrots and celery, the button mushrooms, the bay leaf, parsley, thyme, peppercorns, and tamari into a large stockpot and pour in the filtered water.", "Bring to a boil on high, cover, then lower the heat so the stock barely simmers and cook for 2 hours.", "Let the stock cool fully, then strain it and discard the solids. Pour into glass jars or BPA-free containers; it keeps up to 7 days chilled or up to 3 months frozen."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-003", "Nut Milk", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Homemade nut milk is fresh, creamy, and free of additives.", [I("raw almonds, hazelnuts, or cashews", 1, "cups", "Pantry"), I("filtered water", 4, "cups", "Pantry"), IN("2 or 3 pitted Medjool dates", 1, "", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices")], ["Cover the nuts with cold water and leave them to soak overnight.", "Drain off the soaking water, rinse the nuts well, and drain again.", "Blend the nuts with the filtered water, then the Medjool dates, the vanilla extract, and the cinnamon in a high-speed blender until completely smooth.", "Strain out the solids through a nut milk bag or a jelly bag. Keep the milk chilled in a clean glass jar for as long as 4 days and shake before using."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-004", "Fresh Pasta Dough", "American", ["section-book-plant-based"], "veg", "bowl", 45, "You can easily make your own eggless fresh pasta dough for long shapes such as hand-cut tagliatelle or fettuccine, or filled pasta such as ravioli.", [I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("warm water", 1, "cups", "Pantry"), I("tomato paste and/or 1 pinch saffron crushed in a mortar and pestle (optional)", 1, "tsp", "Pantry"), I("all-purpose flour, plus more for kneading", 3.5, "cups", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices")], ["Whisk the extra-virgin olive oil into the warm water in a small bowl, then whisk in the tomato paste and/or saffron if using.", "Mix the all-purpose flour and kosher salt in a large bowl, pile it onto a wooden board or clean counter, and hollow out a well in the middle. Pour the oil and water into the well.", "With a fork, draw the flour into the liquid bit by bit until almost all of it is absorbed. Knead by hand for about 5 minutes, dusting the surface with flour as needed and adding a few drops of water if the dough feels dry, until it is smooth, firm, and springy.", "Wrap the dough in plastic and let it rest at room temp for 20 minutes while you set up a pasta roller or flour a rolling pin and your work surface.", "Press the dough into a rectangle and roll it out thin (but not see-through) with the machine, or with a rolling pin, giving it a quarter turn after each pass and flipping it often. Keep the board well floured.", "Cut or fill the pasta straight away and boil it in well-salted water for about 3 minutes, until tender. Serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-005", "Smoky Baba Ghanoush", "American", ["section-book-plant-based"], "veg", "roast", 45, "The secret to excellent baba ghanoush is getting the eggplant charred on the outside, with the flesh on the inside collapsed upon itself.", [I("large, firm eggplants", 2, "", "Produce"), IN("Juice of 1 to 1½ medium lemons (¼ cup)", 1, "", "Produce"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("tahini", 3, "tbsp", "Pantry"), I("garlic, smashed and chopped", 2, "cloves", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices")], ["Get the oven heated to 450°F (230°C), or have a grill ready for direct, high heat.", "Lay the eggplants directly on the rack of the oven or grill and roast for about 30 minutes, turning once on the grill, until the skins are blackened and the insides have slumped. In the oven, set a foil-lined baking sheet on the rack underneath to catch drips.", "Move the eggplants to a board with a spatula, split them, pull out the seeds, and scoop the flesh into a fine-mesh sieve resting over a big bowl. Leave to drain for 1 hour, then throw away the liquid.", "Put the drained eggplant in a food processor with the tahini and lemon juice, the garlic, the extra-virgin olive oil, and the kosher salt. Pulse a few times for a chunky dip, or run the machine 1 or 2 minutes for a silky one.", "Spoon into a shallow bowl and serve, or keep sealed in the refrigerator for as long as 5 days."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-006", "Tzatziki Sauce", "American", ["section-book-plant-based"], "veg", "roast", 45, "Cool, creamy, plant-based yogurt combines with cucumber, garlic, and dill in this classic Greek sauce or dip.", [I("medium cucumbers, halved, seeded, and shredded", 2, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("unflavored plant-based yogurt, such as coconut milk or soy", 2, "cups", "Dairy & Eggs"), IN("Juice of 1 medium lemon (3 TB.)", 1, "", "Produce"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("fresh dill, finely chopped", 0.25, "cups", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("garlic, minced", 2, "cloves", "Produce")], ["Toss the shredded cucumbers with the kosher salt in a fine-mesh sieve, set it over a bowl, and let drain for 30 minutes. Press gently and discard the liquid.", "In a medium bowl, fold the drained cucumber together with the yogurt and lemon juice, then the dill, parsley, garlic, and extra-virgin olive oil.", "Chill for 3 to 4 hours so the flavors meld before serving. Stored airtight, it keeps for 3 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-007", "Truffled Mushroom Pate", "American", ["section-book-plant-based"], "veg", "bowl", 45, "This silky Pate with the umami flavors of mushrooms and truffles is an easy-to-make, elegant appetizer.", [I("raw cashews", 1, "cups", "Pantry"), I("(25g) dried porcini mushrooms", 0.5, "oz", "Pantry"), I("boiling water", 0.5, "cups", "Pantry"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("medium shallots, finely chopped (¼ cup)", 2, "", "Produce"), I("garlic, minced", 2, "cloves", "Produce"), I("(8-oz.; 225g) pkg. cremini (baby bella) mushrooms, sliced", 1, "", "Produce"), I("(8-oz.; 225g) pkg. white button mushrooms, sliced", 1, "", "Produce"), I("chopped fresh rosemary, or ½ tsp. dried", 1, "tsp", "Pantry"), I("dry white wine", 0.25, "cups", "Pantry"), I("kosher salt, or to taste", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper, or to taste", 0.25, "tsp", "Herbs & Spices"), I("white (shiro) miso", 1, "tbsp", "Pantry"), I("reduced-sodium tamari", 1, "tbsp", "Pantry"), IN("Juice of ½ medium lemon (1 TB.)", 1, "", "Produce"), I("finely chopped fresh chives", 1, "tbsp", "Produce"), I("truffle oil, or to taste", 1, "tsp", "Pantry")], ["Cover the cashews with cold water and soak for at least 4 hours, then drain, rinse well, and set aside.", "Put the porcini mushrooms in a small bowl, cover with the boiling water, and leave about 5 minutes to soften. Lift them out, swishing to shake off any grit, keep the soaking liquid, and chop the porcini.", "Warm the extra-virgin olive oil in a large sauté pan on medium-high. Cook the shallots and garlic for 2 minutes, stirring the whole time.", "Add the porcini, cremini, and white button mushrooms with the rosemary. Cook about 10 minutes, stirring now and then, until browning; adjust the heat so they sizzle steadily but do not scorch.", "Pour in the white wine to lift the browned bits and cook 1 minute longer. Season with the kosher salt and black pepper and take off the heat.", "Put the cashews, mushroom mixture, miso and tamari, the lemon juice, the chives, and the truffle oil in a food processor. Strain in the porcini liquid, holding back the last 1 or 2 teaspoons with any grit, and blend until perfectly smooth. Adjust the salt and pepper.", "Pack into a large ramekin or terrine mold and chill thoroughly before serving."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-008", "Mushroom Gravy", "American", ["section-book-plant-based"], "veg", "bowl", 45, "This rich, brown, flavorful gravy never disappoints.", [I("grapeseed oil", 5, "tbsp", "Pantry"), I("medium shallots, finely chopped (½ cup)", 2, "", "Produce"), I("garlic, smashed and finely chopped", 1, "cloves", "Produce"), I("(225g) cremini (baby bella) mushrooms, thinly sliced", 8, "oz", "Produce"), I("(225g) shiitake mushrooms, thinly sliced", 8, "oz", "Produce"), I("Mushroom Stock", 4, "cups", "Pantry"), I("low-sodium tamari or soy sauce", 1, "tbsp", "Pantry"), I("all-purpose flour", 3, "tbsp", "Pantry"), I("bourbon (optional)", 1, "tbsp", "Pantry"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Heat 3 tablespoons of the grapeseed oil in a medium sauté pan on medium-high until shimmering but not smoking. Cook the shallots about 5 minutes, stirring now and then, until soft.", "Add the garlic, cremini, and shiitake mushrooms and cook 10 minutes, stirring often, until the mushrooms have given up their juices.", "Pour in the Mushroom Stock and tamari, lower the heat to medium, and let it bubble gently while you make the roux.", "Warm the last 2 tablespoons grapeseed oil in a small saucepan on medium. Whisk in the all-purpose flour and cook about 10 minutes, stirring often, until it turns a deep brown.", "Whisk the roux into the mushrooms and simmer 5 to 10 minutes more, until thickened to your liking. Add the bourbon if using and the black pepper and serve hot. Leftovers keep 3 days in a sealed container in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-009", "Vinaigrette", "American", ["section-book-plant-based"], "veg", "green", 45, "A simple, easily varied vinaigrette you can whisk together in minutes for salads and steamed vegetables.", [I("medium shallot, finely minced (2 TB.)", 1, "", "Produce"), I("minced fresh herbs, such as chives, tarragon, or parsley", 2, "tbsp", "Produce"), I("apple cider vinegar", 0.5, "cups", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("Dijon mustard", 1, "tbsp", "Pantry"), I("extra-virgin olive oil", 0.5, "cups", "Pantry"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Whisk the shallot and fresh herbs with the Dijon mustard, the kosher salt, and the apple cider vinegar together in a small bowl.", "Add the extra-virgin olive oil drop by drop, whisking constantly, until it is all absorbed and the dressing is smooth.", "Whisk in the black pepper. Use straight away, or keep in a sealed jar in the refrigerator for as long as 3 days."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-010", "Nutty Granola", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Making your own granola is so easy, and you can add just what you want.", [I("rolled oats (not instant)", 4, "cups", "Pantry"), I("lightly packed brown sugar", 2, "tbsp", "Pantry"), I("ground cinnamon", 1, "tsp", "Herbs & Spices"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("grapeseed oil", 0.5, "cups", "Pantry"), I("maple syrup", 0.5, "cups", "Pantry"), I("chopped pecans, walnuts, or your favorite nut", 0.5, "cups", "Pantry"), I("raisins", 0.5, "cups", "Pantry"), I("roasted, salted, shelled pumpkin seeds (pepitas)", 0.25, "cups", "Pantry")], ["Heat the oven to 300°F (150°C).", "Stir the rolled oats with the cinnamon, kosher salt, and brown sugar together in a large bowl.", "Whisk the grapeseed oil with the maple syrup in a small bowl, pour it over the oats, and fold with a large spatula until evenly coated.", "Spread the mixture on a large baking sheet and bake 20 to 25 minutes, stirring twice, until toasted and golden.", "Tip into a clean bowl, mix in the pecans, raisins, and pumpkin seeds, and let cool completely. Store in a sealed glass jar for as long as 1 week."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-011", "Whole-Wheat Banana Pecan Pancakes", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Buckwheat flour, white whole-wheat flour, flax meal, and toasted pecans offer a boost of protein in the morning, with the sweet flavor of bananas and warm spices.", [I("soy milk or coconut milk beverage, plus ¼ cup if needed", 1.25, "cups", "Dairy & Eggs"), I("flax meal (ground flaxseeds)", 1, "tbsp", "Pantry"), I("apple cider vinegar", 1, "tsp", "Pantry"), I("large ripe banana, peeled and mashed well", 1, "", "Produce"), I("brown sugar", 1, "tbsp", "Pantry"), I("maple syrup, plus more for serving (optional)", 1, "tbsp", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), I("white whole-wheat flour or whole-wheat pastry flour", 1, "cups", "Pantry"), I("buckwheat flour", 0.3333, "cups", "Pantry"), I("baking powder", 2, "tsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices"), I("ground nutmeg", 0.25, "tsp", "Herbs & Spices"), I("finely chopped toasted pecans", 0.5, "cups", "Pantry"), I("fresh mixed raspberries, blueberries, and/or strawberries (optional)", 1, "cups", "Pantry")], ["Warm ¼ cup of the soy milk in a small saucepan on medium-high.", "Stir the warm milk into the flax meal in a small bowl and set aside.", "In another small bowl, whisk the apple cider vinegar into the rest of the soy milk and leave it to thicken and curdle.", "In a third small bowl, mash the banana with the maple syrup, brown sugar, and vanilla extract. Then whisk in the flax mixture, then the curdled milk.", "Set a cast-iron griddle or frying pan to heat on medium until a drop of water sizzles away instantly.", "Meanwhile, whisk the buckwheat flour and white whole-wheat flour with the cinnamon, nutmeg, kosher salt, and baking powder in a medium bowl. Stir in the wet mixture just until combined, then fold in the pecans. Add a splash more soy milk if needed for a thick batter.", "Lightly grease the griddle and drop in 3 tablespoon-size scoops of batter, spreading them a little. Cook 2 minutes untouched, until bubbles appear, then flip and cook 1½ minutes more. Grease the pan between batches.", "Serve hot with the mixed berries and extra maple syrup if you like."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-012", "Strawberry Muffins", "American", ["section-book-plant-based"], "veg", "bowl", 45, "These tender, biscuitlike muffins are kissed with a little bit of lemon and studded with bits of strawberry.", [I("all-purpose flour", 1.75, "cups", "Pantry"), I("sugar", 0.5, "cups", "Pantry"), I("baking soda", 0.5, "tsp", "Pantry"), I("baking powder", 0.5, "tsp", "Pantry"), I("kosher salt", 0.25, "tsp", "Herbs & Spices"), I("ground nutmeg", 0.25, "tsp", "Herbs & Spices"), I("egg replacer, such as Ener-G", 3, "tsp", "Dairy & Eggs"), I("warm water", 0.25, "cups", "Pantry"), I("vanilla nondairy yogurt", 0.5, "cups", "Dairy & Eggs"), I("grapeseed oil", 0.25, "cups", "Pantry"), I("nondairy milk", 2, "tbsp", "Dairy & Eggs"), I("lemon zest", 1, "tsp", "Produce"), I("freshly squeezed lemon juice", 1, "tsp", "Produce"), I("roughly chopped fresh or frozen strawberries", 1.25, "cups", "Frozen")], ["Heat the oven to 350°F (180°C) and lightly grease a 12-cup muffin tin.", "Whisk the all-purpose flour and sugar with the nutmeg, kosher salt, baking powder, and baking soda together in a medium bowl.", "In a small bowl, beat the egg replacer into the warm water until smooth, then whisk in the yogurt and nondairy milk, the grapeseed oil, and the lemon juice and zest.", "Stir the wet ingredients into the dry ones just until combined; do not overmix. Fold in the strawberries.", "Divide the thick batter among the muffin cups with an ice-cream scoop or large spoon.", "Bake on the lowest rack for 22 to 25 minutes, until the tops spring back when pressed. Cool 5 minutes in the tin, then turn out onto a wire rack. Serve warm or at room temperature."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-013", "Banh Mi Portobello Burgers", "American", ["section-book-plant-based"], "veg", "bowl", 45, "The humble portobello mushroom makes a delicious, all-natural substitute for hamburger patties.", [IN("Juice of 1 medium lime (2 TB.)", 1, "", "Produce"), I("reduced-sodium tamari or soy sauce", 2, "tbsp", "Pantry"), I("toasted sesame oil", 1, "tsp", "Pantry"), I("garlic powder", 0.5, "tsp", "Herbs & Spices"), I("ground ginger", 0.5, "tsp", "Herbs & Spices"), I("large portobello mushrooms, stems removed", 4, "", "Produce"), I("small daikon radish, peeled and shredded (1 cup)", 1, "", "Produce"), I("medium carrot, shredded (½ cup)", 1, "", "Produce"), I("rice vinegar", 0.25, "cups", "Pantry"), I("water", 0.25, "cups", "Pantry"), I("sugar", 1, "tbsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("plant-based mayonnaise, such as Vegenaise", 2, "tbsp", "Pantry"), I("Sriracha hot sauce", 1, "tsp", "Pantry"), I("(4-in.; 10cm) crusty baguette rolls, split", 4, "", "Bakery"), I("English cucumber, thinly sliced", 0.5, "", "Produce"), IN("Cilantro leaves (optional)", 1, "", "Produce")], ["Whisk the tamari and lime juice with the ginger, garlic powder, and toasted sesame oil together in a small bowl.", "Wipe the portobello mushrooms clean with a damp paper towel, put them in a zipper-lock bag, pour in the marinade, seal, and shake gently to coat. Set aside.", "Toss the daikon radish and carrot together in a medium bowl.", "Bring the rice vinegar, water, sugar, and kosher salt to a boil in a small saucepan on medium, stirring until dissolved.", "Pour the hot brine over the daikon and carrot, stir, and let stand about 30 minutes.", "Whisk the mayonnaise and Sriracha together in another small bowl.", "Heat a grill or stovetop grill pan to high. Grill the mushrooms gill side down for 3 minutes, flip, and cook 2 minutes more until juicy and tender. Toast the baguette rolls cut side down on the grill during the last minute.", "Drain the pickled vegetables in a fine-mesh strainer.", "Spread the Sriracha mayo on each roll, layer on English cucumber, add a mushroom, and pile on the pickled vegetables. Scatter cilantro leaves on top if you like and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-014", "Italian Eggplant Cutlet Subs", "American", ["section-book-plant-based"], "veg", "roast", 45, "Crispy breading surrounds tender eggplant slices in these subs, layered on a hearty roll with sliced hot peppers, lettuce, tomato, shaved onion, and plenty of olive oil and red wine vinegar.", [I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("large Italian eggplant, sliced lengthwise in ¼-inch (.5cm) slices", 1, "", "Produce"), I("water", 0.5, "cups", "Pantry"), I("all-purpose flour", 0.5, "cups", "Pantry"), I("Italian-seasoned breadcrumbs", 0.5, "cups", "Pantry"), I("(6-in.; 15.25cm) Italian rolls, sliced horizontally", 4, "", "Bakery"), I("garlic, halved", 1, "cloves", "Produce"), I("olive oil, plus more for frying", 2, "tbsp", "Pantry"), I("medium tomatoes, sliced", 2, "", "Produce"), I("shredded romaine or iceberg lettuce", 2, "cups", "Produce"), I("small red onion, sliced paper thin", 0.5, "", "Produce"), IN("Sliced hot cherry peppers in oil, drained (optional)", 1, "", "Pantry"), I("red wine vinegar", 2, "tbsp", "Pantry")], ["Salt the eggplant slices with the kosher salt, put them in a colander, and leave 10 minutes to drain. Pat dry, pressing gently to remove the bitter juices.", "In separate shallow bowls, set out the water, the all-purpose flour, and the breadcrumbs.", "Coat each eggplant slice: water, then flour, then water again, then breadcrumbs, and finish with a final light dusting of flour, shaking off the extra. Repeat with all the slices.", "In a large fry pan on medium-high, warm enough olive oil to reach ¼ inch (.5cm) up the sides. Once shimmering, fry the eggplant in small batches without crowding, about 2 minutes per side, until crisp and golden. Drain on a paper towel-lined baking sheet.", "Heat the broiler to high. Toast the split Italian rolls on a baking sheet for 2 or 3 minutes until golden, rub them with the cut garlic, and drizzle with the 2 tablespoons olive oil.", "Share the eggplant among the rolls and top with the tomatoes, lettuce, and red onion. Add hot cherry peppers if using, sprinkle with the red wine vinegar, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-015", "Oyster Mushroom Po'boys", "American", ["section-book-plant-based"], "veg", "green", 45, "Oyster mushrooms are breaded in cornmeal, quickly fried until crisp, and slathered with a savory dressing and shredded lettuce on soft rolls.", [I("plant-based mayonnaise", 0.25, "cups", "Pantry"), I("ketchup", 1, "tbsp", "Pantry"), I("grated fresh sweet onion", 1, "tbsp", "Produce"), I("sweet pickle relish", 1, "tbsp", "Pantry"), I("finely chopped chives", 1, "tsp", "Produce"), IN("Grapeseed oil", 1, "", "Pantry"), I("water", 0.5, "cups", "Pantry"), I("all-purpose flour", 1, "cups", "Pantry"), I("fine cornmeal", 1, "cups", "Pantry"), I("(340g) oyster mushrooms, pulled apart into \"oyster-size\" chunks", 0.75, "lb", "Produce"), I("Old Bay seasoning", 1, "tsp", "Herbs & Spices"), I("sweet paprika", 0.5, "tsp", "Herbs & Spices"), I("(6-in.; 15.25cm) soft \"sub\" rolls, sliced horizontally", 4, "", "Bakery"), I("shredded iceberg lettuce", 2, "cups", "Produce"), IN("Lemon wedges", 1, "", "Produce")], ["Mix the mayonnaise, ketchup, grated onion, pickle relish, and chives in a small bowl. Keep chilled until needed; it can be made up to 3 days ahead.", "Pour enough grapeseed oil into a large fry pan to come ¾ inch (2cm) up the sides and heat on medium.", "Set out three shallow bowls with the water, the all-purpose flour, and the cornmeal.", "Coat each oyster mushroom piece: water, flour, water again, then a thorough roll in cornmeal. Repeat until all are coated.", "Fry the mushrooms for roughly 3 minutes until golden all over, flipping them once or twice. Drain on paper towels and dust with the Old Bay seasoning and paprika.", "Heap the mushrooms onto the sub rolls, spoon about 1 tablespoon of the dressing over each, add the iceberg lettuce, and serve with lemon wedges."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-016", "Muffuletta", "American", ["section-book-plant-based"], "veg", "green", 45, "Muffuletta is a classic New Orleans sandwich that features a whole round loaf of crusty bread, hollowed out and slathered in a salty, savory olive salad of the same name.", [I("pimiento-stuffed green olives, roughly chopped", 0.75, "cups", "Pantry"), I("pitted oil-cured black olives, roughly chopped", 0.5, "cups", "Pantry"), I("giardiniera mix, such as Victoria, roughly chopped", 0.5, "cups", "Pantry"), I("salt-packed capers, rinsed and drained", 2, "tbsp", "Pantry"), I("finely chopped celery", 2, "tbsp", "Produce"), I("finely chopped carrot", 2, "tbsp", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("dried oregano", 1, "tsp", "Pantry"), I("extra-virgin olive oil", 4, "tbsp", "Pantry"), IN("Pinch crushed red pepper flakes", 1, "", "Herbs & Spices"), I("balsamic vinegar", 2, "tbsp", "Pantry"), I("portobello mushrooms, cut in ¼-in.-thick (.5cm-thick) slices", 3, "", "Produce"), I("large zucchini, sliced lengthwise in ¼-in.-thick (.5cm-thick) slices", 1, "", "Produce"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("(10-in.; 20cm) round loaf country bread, preferably semolina", 1, "", "Bakery"), I("baby arugula", 2, "cups", "Produce"), I("small red onion, sliced paper thin", 0.5, "", "Produce"), I("red wine vinegar", 2, "tbsp", "Pantry")], ["For the olive salad, mix both kinds of olives with the giardiniera and capers, the celery, carrot, and garlic, the oregano, and 2 tablespoons of the extra-virgin olive oil in a medium bowl. Add the red pepper flakes and set aside.", "Heat a grill pan or grill for direct, high heat.", "Whisk 1 tablespoon of the olive oil with the balsamic vinegar in a large dish, turn the portobello mushrooms and zucchini in it, and season with the kosher salt and black pepper. Grill the vegetables 2 minutes per side and set aside.", "Split the bread loaf horizontally and pull out most of the soft crumb from both halves.", "Lay the grilled mushrooms and zucchini over the bread, then spoon on the olive salad. Add the arugula and red onion, then drizzle with the last tablespoon of olive oil and the red wine vinegar. Close the loaf, press down gently, and cut into quarters. Serve, or wrap tightly and hold for as long as 4 hours."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-017", "Falafel Burgers", "American", ["section-book-plant-based"], "veg", "green", 45, "These pita sandwiches pack all the deliciously spiced flavor of traditional falafel without the deep-fried fat.", [I("flax meal (ground flaxseeds)", 1, "tbsp", "Pantry"), IN("4 or 5 TB. warm water", 1, "", "Pantry"), I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("medium yellow onion, finely chopped (about ½ cup)", 1, "", "Produce"), I("ground cumin", 2, "tsp", "Herbs & Spices"), I("ground coriander", 1, "tsp", "Herbs & Spices"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("lemon zest", 1, "tsp", "Produce"), IN("Juice of 2 medium lemons (4 TB.)", 1, "", "Produce"), I("finely chopped fresh cilantro", 0.25, "cups", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("(14-oz.; 400g) cans chickpeas, drained and rinsed (or 3 cups cooked chickpeas), ¼ cup liquid reserved", 2, "", "Pantry"), I("fresh breadcrumbs (from 1 or 2 slices bread)", 1, "cups", "Pantry"), I("grapeseed oil", 3, "tbsp", "Pantry"), I("tahini", 2, "tbsp", "Pantry"), I("garlic, minced", 1, "cloves", "Produce"), I("small loaves pita bread, split on one side", 4, "", "Bakery"), I("medium plum tomatoes, finely diced (½ cup)", 2, "", "Produce"), I("thinly sliced romaine lettuce", 0.5, "cups", "Produce"), I("medium red onion, thinly sliced", 0.5, "", "Produce")], ["Stir the flax meal into 3 tablespoons of the warm water in a small bowl and set aside.", "Heat 2 tablespoons of the extra-virgin olive oil in a small sauté pan on medium until shimmering. Add the yellow onion, cumin, and coriander and cook 5 minutes, stirring constantly, until the onion softens and starts to brown.", "Add the lemon zest and 2 tablespoons of the lemon juice, then season with the kosher salt and black pepper. Take off the heat and mix in the cilantro and parsley.", "Pulse the chickpeas, breadcrumbs, and onion mixture in a food processor for about 1 minute until chunky, and scoop out ½ cup. Keep processing, adding the flax mixture, the rest of the olive oil, and the reserved chickpea liquid, until smooth. Return the scooped-out portion and pulse once or twice to mix it through.", "Shape into 8 even patties about 3 inches (7.5cm) across and 1 inch (2.5cm) thick.", "Heat the grapeseed oil in a large nonstick sauté pan on medium-high and fry the patties, flipping once, until golden on both sides and hot in the middle.", "Whisk the last 2 tablespoons lemon juice with the tahini and garlic in a small bowl, thinning with 1 or 2 tablespoons warm water until smooth.", "Tuck 2 patties into each pita, add the plum tomatoes, romaine lettuce, and red onion, spoon over the tahini sauce, and serve straight away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-018", "Pan Bagnat", "American", ["section-book-plant-based"], "veg", "roast", 45, "Chickpeas and artichoke hearts are seasoned with dulse, a seaweed flake, along with capers and vinegar, for a delicious new take on this Nicoise 'street food' classic.", [I("(14-oz.; 400g) can chickpeas, rinsed and drained", 1, "", "Pantry"), I("(6-oz.; 170g) jar marinated grilled artichoke hearts, drained, 2 TB. marinade reserved", 1, "", "Pantry"), I("salted capers, rinsed and drained", 1, "tbsp", "Pantry"), I("red wine vinegar", 1, "tbsp", "Pantry"), I("dulse flakes", 1, "tsp", "Pantry"), I("crusty round whole-wheat rolls, sliced", 4, "", "Bakery"), I("large tomatoes, sliced", 2, "", "Produce"), I("leaves romaine lettuce", 4, "", "Produce"), I("small red onion, sliced paper thin", 0.5, "", "Produce"), I("chopped, pitted Niçoise olives", 2, "tbsp", "Pantry"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Pulse the chickpeas, artichoke hearts, capers, dulse flakes, red wine vinegar, and the saved artichoke marinade in a food processor until you have a coarse, chunky spread.", "Spread the chickpea mixture over the whole-wheat rolls and layer on the tomatoes, romaine lettuce, and red onion.", "Scatter the Niçoise olives on top, give each sandwich 1 tablespoon of extra-virgin olive oil, then grind over plenty of black pepper. Serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-019", "Korean Barbecue Sliders", "American", ["section-book-plant-based"], "veg", "dessert", 45, "These little sandwiches pack a lot of flavor.", [I("(8-oz.; 225g) pkg. tempeh", 1, "", "Pantry"), IN("½ cup plus 1 tsp. reduced-sodium tamari", 1, "", "Pantry"), I("brown sugar, firmly packed", 0.5, "cups", "Pantry"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("sambal oelek (chili garlic sauce)", 1, "tbsp", "Pantry"), I("finely chopped fresh ginger", 1, "tbsp", "Produce"), IN("1 TB. plus 2 tsp. rice vinegar", 1, "", "Pantry"), I("toasted sesame oil", 2, "tsp", "Pantry"), I("cornstarch", 1, "tbsp", "Pantry"), I("cold water", 1, "tbsp", "Pantry"), I("toasted sesame seeds", 1, "tsp", "Pantry"), I("granulated sugar", 1, "tsp", "Pantry"), I("small buns, such as whole-wheat dinner rolls or slider buns", 8, "", "Bakery"), I("shredded romaine lettuce", 1, "cups", "Produce"), I("thinly sliced radishes", 0.5, "cups", "Produce")], ["Put the tempeh in a small sauté pan, add water to cover, and bring to a simmer on medium. Cover and cook 10 minutes, then uncover, drain, and let cool.", "Slice the tempeh in half horizontally and cut each half into 4 pieces to make 8 mini patties. Arrange them in one layer in a shallow pan.", "In a small saucepan on high, bring ½ cup of the tamari, the garlic and ginger, the sambal oelek, the brown sugar, 1 tablespoon of the rice vinegar, and 1 teaspoon of the sesame oil to a boil.", "Stir the cornstarch into the cold water until smooth, add it to the pan, and cook about 1 minute until the sauce thickens.", "Pour the hot sauce over the tempeh and marinate 30 minutes at room temperature, or up to 24 hours in the refrigerator.", "Heat the broiler to high. For the slaw dressing, whisk the remaining 2 teaspoons rice vinegar, 1 teaspoon tamari, and 1 teaspoon sesame oil with the sesame seeds and granulated sugar in a medium bowl.", "Broil the tempeh, turning once, until hot and crisp, and set one piece on each bun.", "Toss the romaine lettuce and radishes with the dressing, pile onto the sliders, and serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-020", "Grandma's Chicken-y Noodle Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "This soup is just the thing if you or someone you love is feeling under the weather.", [I("(55g) spaghetti or fettuccine, broken into small pieces", 2, "oz", "Pantry"), I("extra-virgin olive oil", 1, "tbsp", "Pantry"), I("medium yellow onion, finely chopped", 1, "", "Produce"), I("large carrot, cut in ¼-in. (.5cm) dice (¾ cup)", 1, "", "Produce"), IN("1 or 2 medium stalks celery, cut in ¼-in. (.5cm) dice (¾ cup)", 1, "", "Produce"), I("small parsnip, cut in ¼-in. (.5cm) dice (½ cup)", 1, "", "Produce"), I("garlic, minced", 1, "cloves", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("Golden Chicken-y Stock or vegetable stock", 4, "cups", "Pantry"), I("nutritional yeast", 1, "tsp", "Pantry"), I("reduced-sodium tamari", 0.5, "tsp", "Pantry"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("finely chopped fresh Italian flat-leaf parsley", 1, "tbsp", "Produce"), I("finely chopped fresh dill", 1, "tbsp", "Produce")], ["Boil the spaghetti in a medium pot of salted water on high until al dente, following the package timing. Drain, rinse under cold water, and set aside.", "Warm the extra-virgin olive oil in a large saucepan on medium-high. Add the yellow onion, turn the heat to medium, and cook 5 to 10 minutes, stirring often, until soft and golden.", "Stir in the carrot, parsnip, and celery with the garlic and kosher salt and give it 3 minutes.", "Pour in the Golden Chicken-y Stock and add the nutritional yeast, tamari, and black pepper. Bring to a boil on high, then lower to medium and simmer 10 minutes.", "Add the cooked spaghetti and heat 1 minute more.", "Finish with the parsley and dill and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-021", "Ginger Kale Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "The flavors of this soup are perfect-just enough ginger and garlic to stand up to the hearty kale and shiitakes, but light and gentle enough for someone who isn't feeling well.", [I("sesame oil", 1, "tbsp", "Pantry"), I("(2-in.; 5cm) piece fresh ginger, peeled and finely chopped (2 TB.)", 1, "", "Produce"), I("garlic, peeled and finely chopped", 3, "cloves", "Produce"), I("scallions, thinly sliced, white and green parts separated", 4, "", "Produce"), I("large carrot, peeled and thinly sliced", 1, "", "Produce"), I("large stalks celery, thinly sliced", 2, "", "Produce"), I("vegetable stock", 8, "cups", "Pantry"), I("tamari", 1, "tsp", "Pantry"), I("dried shiitake mushrooms, rinsed well", 4, "", "Pantry"), I("(170g) fresh shiitake mushrooms, stems removed, and thinly sliced", 6, "oz", "Produce"), I("leaves lacinato kale, stemmed and sliced into thin ribbons", 8, "", "Produce"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce"), I("Sriracha, or to taste (optional)", 1, "tsp", "Pantry"), I("cooked basmati or jasmine rice", 2, "cups", "Pantry")], ["Heat the sesame oil in a medium saucepan on medium-high. Add the ginger, garlic, and white scallion slices and stir for 1 minute.", "Add the carrot and celery and stir 1 minute more.", "Pour in the vegetable stock, add the tamari and dried shiitake mushrooms, and simmer 15 minutes.", "Add the fresh shiitake mushrooms and kale, cover, and simmer 5 minutes.", "Fish out the dried shiitakes and take the pan off the heat. Stir in the lemon juice and a little Sriracha if you like.", "Spoon the rice into 4 bowls, ladle the soup over, and top with the green scallion slices."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-022", "Mushroom Barley Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Fortifying Polish mushroom barley soup, or krupnik, contains fresh and dried mushrooms, pearl barley, and root vegetables.", [I("vegetable stock", 9, "cups", "Pantry"), I("(25g) dried borowik, porcini, or forest mix mushrooms", 1, "oz", "Pantry"), I("grapeseed oil", 2, "tbsp", "Pantry"), I("large yellow onions, finely chopped (3 cups)", 2, "", "Produce"), I("small stalks celery, finely chopped (1 cup)", 4, "", "Produce"), I("small carrots, finely chopped (1 cup)", 2, "", "Produce"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("(340g) button mushrooms, thinly sliced", 12, "oz", "Produce"), I("pearl barley", 0.75, "cups", "Pantry"), I("medium yellow potatoes (such as Yukon gold), peeled and cut in ½-in. (1.25cm) dice", 4, "", "Produce"), I("bay leaf", 1, "", "Herbs & Spices"), I("finely chopped fresh Italian flat-leaf parsley", 4, "tbsp", "Produce"), I("kosher salt, plus more to taste", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), IN("Juice of ½ medium lemon (1 TB.)", 1, "", "Produce")], ["Heat 1 cup of the vegetable stock to a simmer in a small saucepan on medium.", "Rinse the dried mushrooms, put them in a small bowl, and pour the hot stock over them. Leave 10 minutes to soften.", "Lift the mushrooms out, swishing to loosen any grit, squeeze lightly, and chop finely. Keep the soaking liquid.", "Warm the grapeseed oil in a large, heavy soup pot on medium. Cook the yellow onions, celery, and carrots for 10 minutes, stirring often.", "Stir in the button mushrooms, the chopped soaked mushrooms, and the garlic and let them cook 5 minutes.", "Strain the soaking liquid into the pot through a sieve lined with cheesecloth. Add the remaining 8 cups stock, raise the heat to high, and let it come to a boil.", "Add the pearl barley, potatoes, bay leaf, 2 tablespoons of the parsley, the kosher salt, and black pepper. Lower the heat to medium-low and cook about 45 minutes, until the barley and vegetables are tender.", "Off the heat, remove the bay leaf and stir in the lemon juice and the rest of the parsley. Adjust the salt and serve hot. Keeps up to 5 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-023", "Curried Cauliflower Coconut Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Creamy cauliflower is accented with warm spices, coconut milk, and fresh lime juice in this soup.", [I("grapeseed oil", 1, "tbsp", "Pantry"), I("medium yellow onion, finely chopped", 1, "", "Produce"), I("large carrot, finely chopped (¾ cup)", 1, "", "Produce"), I("medium stalks celery, finely chopped (½ cup)", 2, "", "Produce"), I("garlic, minced", 1, "cloves", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("medium head cauliflower, cut into florets (about 4 or 5 cups)", 1, "", "Produce"), I("vegetable stock", 4, "cups", "Pantry"), I("(15-oz.; 420g) can full-fat coconut milk", 1, "", "Pantry"), I("curry powder", 1, "tsp", "Herbs & Spices"), I("sambal oelek (chili garlic paste)", 0.5, "tsp", "Pantry"), IN("Juice of ½ lime (1 tsp.)", 1, "", "Produce"), IN("Fresh cilantro leaves", 1, "", "Produce")], ["Warm the grapeseed oil in a medium soup pot on medium-high. Cook the yellow onion and garlic with the celery, carrot, and kosher salt about 5 minutes, stirring gently, until the onion is soft.", "Add the cauliflower and vegetable stock, lower the heat to medium-low, cover, and cook about 10 minutes until the cauliflower is tender.", "Stir in the curry powder, sambal oelek, and coconut milk and give it 2 minutes more.", "Off the heat, add the lime juice, then blend until smooth with a stick blender, or in batches in a countertop blender. Serve hot, topped with a few cilantro leaves."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-024", "Smoky White Bean and Tomato Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Protein-packed white beans are cooked with garlic and fragrant rosemary and enhanced with tomatoes, smoked sea salt, and aromatic vegetables in this easy soup.", [I("dry great northern beans or other small white beans, soaked 6 hours or overnight", 2, "cups", "Pantry"), I("vegetable stock or filtered water", 8, "cups", "Pantry"), I("garlic, thinly sliced", 4, "cloves", "Produce"), I("finely chopped fresh rosemary", 1, "tbsp", "Herbs & Spices"), I("finely chopped fresh thyme or ½ tsp. dried", 1, "tsp", "Pantry"), I("tomato paste", 0.25, "cups", "Pantry"), I("smoked sea salt", 1, "tsp", "Herbs & Spices"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("large yellow onion, chopped (about 1½ cups)", 1, "", "Produce"), I("small stalks celery, cut in ¼-in. (.5cm) dice (1 cup)", 4, "", "Produce"), I("(28-oz.; 800g) can diced tomatoes, with juice", 1, "", "Pantry"), IN("¼ cup plus 2 TB. extra-virgin olive oil", 1, "", "Pantry"), I("crushed red pepper flakes", 0.25, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("apple cider vinegar", 1, "tbsp", "Pantry")], ["Drain and rinse the soaked beans, put them in a large soup pot, and cover with the vegetable stock. Add the rosemary, thyme, and garlic and let it come to a boil on high.", "Lower to a simmer and cook, partly covered, for 30 minutes. The beans should be nearly done but still a little firm; if not, give them 10 to 15 minutes longer.", "Loosen the tomato paste with a ladle of hot stock in a small bowl and add it to the pot with the yellow onion and celery, the tomatoes and their juice, both salts, ¼ cup of the olive oil, red pepper flakes, and black pepper.", "Bring back to a boil on high, then turn it down to medium-low and let it simmer, lid off, for 30 minutes, until the beans are fully tender.", "Off the heat, stir in the apple cider vinegar and the last 2 tablespoons olive oil. If you like, blend ½ cup of the soup and stir it back in to thicken slightly. Serve hot. Keeps several days chilled or up to 3 months frozen."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-025", "Classic Vegetable Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "This comforting soup comes together very quickly.", [I("alphabet pasta", 0.75, "cups", "Pantry"), I("grapeseed oil", 1, "tsp", "Pantry"), I("medium yellow onion, finely chopped", 1, "", "Produce"), I("large stalks celery, finely chopped (½ cup)", 2, "", "Produce"), I("large red bell pepper, finely chopped (¼ cup)", 0.25, "", "Produce"), I("garlic, minced", 1, "cloves", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("ground allspice", 0.25, "tsp", "Herbs & Spices"), I("vegetable stock", 4, "cups", "Pantry"), I("tomato-vegetable juice", 2, "cups", "Produce"), I("frozen mixed vegetables (green beans, peas, carrots, corn)", 2, "cups", "Produce"), IN("Juice of ½ lemon (1 TB.)", 1, "", "Produce")], ["Boil the alphabet pasta in a pot of water on medium-high according to the package, then drain and set aside.", "Warm the grapeseed oil in a medium soup pot on medium-high and cook the yellow onion and red bell pepper with the celery, garlic, and kosher salt about 5 minutes, stirring often, until soft.", "Add the allspice, vegetable stock, tomato-vegetable juice, and mixed vegetables and bring to a boil. Turn the heat to medium, partly cover, and cook 10 minutes.", "Add the pasta and lemon juice, heat through for 1 minute, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-026", "Mushroom and Cabbage Borscht", "American", ["section-book-plant-based"], "veg", "soup", 45, "This sweet and sour Ukrainian standard is made throughout Eastern and Central Europe with many variations.", [I("small beets", 4, "", "Produce"), IN("1 TB. plus 1 tsp. grapeseed oil", 1, "", "Pantry"), I("medium yellow onions, halved and thinly sliced", 2, "", "Produce"), I("medium carrots, thinly sliced", 2, "", "Produce"), I("large stalks celery, thinly sliced", 3, "", "Produce"), I("(10-oz.; 285g) pkg. white button mushrooms, thinly sliced", 1, "", "Produce"), I("sugar", 1, "tbsp", "Pantry"), I("kosher salt", 2, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("tomato paste", 2, "tbsp", "Pantry"), I("mushroom stock", 8, "cups", "Pantry"), I("small head savoy cabbage, shredded (about 6 cups)", 1, "", "Produce"), I("freshly squeezed lemon juice, or apple cider vinegar", 2, "tbsp", "Pantry"), I("finely chopped fresh dill", 0.25, "cups", "Produce")], ["Heat the oven to 400°F (200°C).", "Scrub the beets without peeling, set them on a parchment-lined baking sheet, and roast about 30 minutes until tender. Let cool a little, then peel and cut into ¼-inch (.5cm) cubes. This can be done a day ahead.", "Warm 1 tablespoon of the grapeseed oil in a large soup pot on medium-high. Add the yellow onions, carrots, celery, mushrooms, sugar, and kosher salt and cook 5 to 10 minutes, stirring often, until the onions soften and everything starts to color.", "Mix in the black pepper and tomato paste, then add the mushroom stock and the beets. Bring to a boil on high, add the savoy cabbage, then lower to medium-low and cook partly covered about 30 minutes, stirring now and then, until the cabbage is tender.", "Off the heat, add the lemon juice and dill and serve. Keeps 3 days chilled; good hot or cold."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-027", "Split-Pea Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Smoked sea salt is the secret to creating the smoky flavor that characterizes an excellent pea soup.", [I("split peas (green, yellow, or a mix of both, about 1½ lb.; 680g)", 4, "cups", "Produce"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("large yellow onion, chopped (about 1½ cups)", 1, "", "Produce"), I("medium carrots, cut in ¼-in. (.5cm) dice (1 cup)", 2, "", "Produce"), I("medium stalks celery, cut in ¼-in. (.5cm) dice (1 cup)", 4, "", "Produce"), I("garlic, minced", 2, "cloves", "Produce"), I("smoked sea salt", 1, "tsp", "Herbs & Spices"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("dried thyme", 0.5, "tsp", "Pantry"), I("crumbled dried sage", 0.5, "tsp", "Pantry"), I("vegetable stock", 6, "cups", "Pantry"), IN("4 to 6 cups filtered water", 1, "", "Pantry"), IN("Pinch cayenne", 1, "", "Herbs & Spices"), IN("Pinch crushed red pepper flakes", 1, "", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("dry white wine", 0.25, "cups", "Pantry"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce")], ["Sort through the split peas for stones or debris, rinse them well, and set aside.", "Warm the extra-virgin olive oil in a large soup pot on medium-high. Add the yellow onion and garlic, the celery and carrots, the thyme and sage, and both salts, turn the heat to medium, and cook 5 minutes, stirring often, until softened.", "Add the split peas, vegetable stock, 4 cups of the filtered water, cayenne, and red pepper flakes and cook about 30 minutes, stirring often, until the peas collapse.", "Add the black pepper, white wine, and lemon juice. Take off the heat and blend smooth with an immersion blender or in batches. Thin with more water as needed and adjust the seasoning.", "Serve hot. Frozen airtight, it keeps up to 3 months."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-028", "Creamy Corn Chowder", "American", ["section-book-plant-based"], "veg", "soup", 45, "Almonds lend a creamy consistency to this delicious soup, which is brimming with potatoes, corn, and aromatic vegetables.", [I("blanched almonds", 1, "cups", "Pantry"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("large yellow onion, finely chopped (about 1½ cups)", 1, "", "Produce"), I("small stalks celery, finely chopped (½ cup)", 2, "", "Produce"), I("medium red bell pepper, finely chopped (½ cup)", 0.5, "", "Produce"), I("medium carrot, finely chopped (½ cup)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("all-purpose flour", 2, "tbsp", "Pantry"), I("light vegetable stock", 6, "cups", "Pantry"), I("large Yukon gold potatoes, peeled and cut into ¼-in. (.5cm) dice (2 cups)", 3, "", "Produce"), I("corn kernels (shucked from about 4 ears corn)", 6, "cups", "Produce"), I("plant-based butter", 1, "tbsp", "Dairy & Eggs"), I("freshly squeezed lemon juice", 1, "tsp", "Produce"), I("hot sauce, such as Sriracha", 0.5, "tsp", "Pantry"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices")], ["Cover the almonds with cold water and soak overnight. Drain, rinse well, drain again, and set aside.", "Warm the extra-virgin olive oil in a large soup pot on medium and cook the yellow onion 5 minutes, stirring often.", "Stir in the red bell pepper, carrot, and celery with the kosher salt for 3 minutes more, until soft and just starting to color.", "Dust in the all-purpose flour and keep stirring 1 minute.", "Whisk in the vegetable stock and bring to a boil. Set aside 1 cup of the stock, then add the potatoes and corn.", "Blend the almonds with the reserved cup of stock until smooth, stir it into the pot, and simmer until the potatoes are tender.", "Finish with the lemon juice and hot sauce, the plant-based butter, and the black pepper and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-029", "Tom Yum Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Tom yum has an addictive flavor that's tart, tangy, and spicy all at once, with the exotic flavors of lemongrass, galangal (Thai ginger), Kaffir lime, and plenty of hot chiles.", [I("large stalks fresh lemongrass", 2, "", "Produce"), I("coconut oil or grapeseed oil", 1, "tsp", "Pantry"), I("finely chopped galangal or ginger", 2, "tbsp", "Produce"), I("Kaffir lime leaves, fresh or frozen, or the zest of 1 medium lime", 3, "", "Produce"), I("small fresh hot red chile pepper, such as Thai bird chile or Serrano, thinly sliced", 1, "", "Produce"), I("sambal oelek (chili garlic sauce)", 2, "tsp", "Pantry"), I("Golden Chicken-y Stock or vegetable stock", 5, "cups", "Pantry"), I("(170g) white button mushrooms, sliced", 6, "oz", "Produce"), I("(115g) firm silken tofu, cut in ½-in. (1.25cm) cubes", 0.25, "lb", "Dairy & Eggs"), I("reduced-sodium tamari", 2, "tbsp", "Pantry"), IN("Juice of 1½ medium limes (2 TB.)", 1, "", "Produce"), I("finely chopped fresh cilantro", 0.25, "cups", "Produce")], ["Strip the tough outer layer from the lemongrass, bruise the stalks with the flat of a knife, and chop finely.", "Warm the coconut oil in a medium saucepan on medium-high. Add the lemongrass, galangal, Kaffir lime leaves, chile pepper, and sambal oelek, stirring for 1 minute.", "Pour in the Golden Chicken-y Stock with the tamari, then add the tofu and mushrooms and let it come to a boil.", "Lower to medium and cook 10 minutes until the mushrooms are tender.", "Off the heat, pull out the lime leaves, add the lime juice and cilantro, and serve. The soup can be made a day ahead; add the lime juice and cilantro just before serving."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-030", "Miso Udon Bowl", "American", ["section-book-plant-based"], "veg", "soup", 45, "Miso soup makes a nourishing meal with the addition of mushrooms, tofu, tender baby spinach, and hearty udon noodles.", [I("(8-oz.; 225g) pkg. udon noodles", 1, "", "Pantry"), I("kombu stock or vegetable stock", 4, "cups", "Pantry"), I("grapeseed oil", 1, "tsp", "Pantry"), I("(4-oz.; 100g) pkg. shiitake mushrooms, stemmed and thinly sliced (about 1½ cups)", 1, "", "Produce"), I("(1-in.; 2.5cm) piece fresh ginger, finely grated (2 TB.)", 1, "", "Produce"), I("garlic, minced", 1, "cloves", "Produce"), I("wakame (seaweed)", 1, "cups", "Pantry"), I("firm silken tofu, cut into ½-in. (1.25cm) cubes", 0.5, "pkg", "Dairy & Eggs"), I("white (shiro) miso paste", 2, "tbsp", "Pantry"), I("(5-oz.; 140g) pkg. baby spinach", 1, "", "Produce")], ["Boil the udon noodles following the package directions, drain, rinse under cold water, and set aside.", "Bring the kombu stock to a simmer in a small saucepan on medium-high.", "Warm the grapeseed oil in a medium saucepan on medium-high and sauté the shiitake mushrooms 1 minute. Add the ginger and garlic and cook 30 seconds.", "Pour in the hot stock, bring to a boil, then drop to a simmer. Add the wakame and tofu and cook 5 minutes.", "Whisk the miso into ½ cup of the soup in a small bowl.", "Add the spinach and noodles to the pot and cook 1 minute until the spinach wilts. Off the heat, stir in the miso mixture and serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-031", "Gumbo", "American", ["section-book-plant-based"], "veg", "soup", 45, "Gumbo filé is an amazing Creole stew layered with flavor.", [I("grapeseed oil", 0.5, "cups", "Pantry"), I("all-purpose flour", 0.5, "cups", "Pantry"), I("large yellow onion, finely chopped (1½ cups)", 1, "", "Produce"), I("medium stalks celery, finely chopped (2 cups)", 4, "", "Produce"), I("medium green bell pepper, ribs and seeds removed, and finely chopped (1 cup)", 1, "", "Produce"), I("medium red bell pepper, ribs and seeds removed, and finely chopped (1 cup)", 1, "", "Produce"), I("garlic, chopped", 6, "cloves", "Produce"), I("vegetable stock", 6, "cups", "Pantry"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("veggie Andouille sausage, thinly sliced", 2, "links", "Pantry"), I("(450g) oyster mushrooms, roughly chopped", 1, "lb", "Produce"), I("sweet paprika", 1, "tsp", "Herbs & Spices"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("Creole seasoning", 0.5, "tsp", "Herbs & Spices"), I("dried oregano", 0.5, "tsp", "Pantry"), I("dried thyme", 0.5, "tsp", "Pantry"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("ground allspice", 0.25, "tsp", "Herbs & Spices"), IN("Pinch cayenne", 1, "", "Herbs & Spices"), I("(350ml) amber beer", 12, "fl oz", "Pantry"), I("(14-oz.; 400g) can diced fire-roasted tomatoes, with juice", 1, "", "Pantry"), I("balsamic vinegar", 1, "tbsp", "Pantry"), I("vegan Worcestershire sauce, such as Annie's", 1, "tbsp", "Pantry"), I("Louisiana hot sauce, such as Crystal", 1, "tsp", "Pantry"), I("filé powder, such as Tony Chachere's", 2, "tsp", "Herbs & Spices"), I("thinly sliced scallions, white and green parts", 0.5, "cups", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 0.25, "cups", "Produce"), I("dark rum (optional)", 2, "tbsp", "Pantry")], ["Heat the grapeseed oil in a large soup pot on medium, whisk in the all-purpose flour, and keep stirring with a wooden spoon until the roux turns a golden caramel brown.", "Add the yellow onion, celery, and green and red bell peppers and cook 10 minutes more, stirring often; lower to medium-low if it threatens to burn.", "Add half the garlic and stir 1 minute, then pour in the vegetable stock, bring to a boil, and drop to a gentle simmer.", "Meanwhile, heat the extra-virgin olive oil in a wide sauté pan on medium. Cook the Andouille sausage 1 minute, then lift it out into a bowl with a slotted spoon.", "Add the oyster mushrooms and the rest of the garlic to the pan and cook until golden. Stir in the Creole seasoning and paprika, the oregano and thyme, the allspice and cayenne, and the kosher salt and black pepper for 1 minute.", "Pour in the amber beer, raise the heat to high, and scrape the pan to loosen every browned bit.", "Tip the mushroom mixture into the soup pot with the tomatoes and their juice, hot sauce, Worcestershire sauce, and balsamic vinegar. Let it come to a boil, then simmer on low to medium-low for 1 hour, stirring now and then.", "Return the sausage to the pot with the filé powder and simmer 5 minutes.", "Finish with the scallions, parsley, and dark rum if using, and serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-032", "Giambotta (Italian Summer Vegetable Stew)", "American", ["section-book-plant-based"], "veg", "bowl", 45, "My grandmother often made this summer vegetable stew with ingredients fresh from the garden, and it was amazing.", [I("medium eggplant, quartered and cut in ½-in. (1.25cm) slices", 1, "", "Produce"), I("kosher salt", 2, "tsp", "Herbs & Spices"), I("(225g) flat Italian green beans, trimmed", 0.5, "lb", "Produce"), I("large white potatoes, unpeeled", 3, "", "Produce"), I("medium plum tomatoes", 12, "", "Produce"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("large yellow onions, halved and thinly sliced", 2, "", "Produce"), I("garlic, smashed and roughly chopped", 2, "cloves", "Produce"), I("red bell peppers, ribs and seeds removed, and thinly sliced", 2, "", "Produce"), I("large zucchini, halved and thinly sliced", 2, "", "Produce"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("fresh basil leaves", 0.25, "cups", "Produce")], ["Toss the eggplant with 1 teaspoon of the kosher salt in a colander set over a bowl. After 30 minutes, discard the liquid, rinse the eggplant, and squeeze out the excess water.", "Set a medium pot of salted water on high and let it boil. Cook the green beans 5 minutes, lift them into ice water with a slotted spoon, drain, and set aside.", "Boil the potatoes in the same pot, covered with water, for about 15 minutes until tender. Move them to a board to cool a little.", "Core the plum tomatoes and cut a small X in the base of each. Using the same boiling water (topped up if needed), blanch them in batches for about 1 minute and plunge into ice water. Peel, seed, and slice them, keeping the tomatoes and their juice in a bowl.", "Warm the extra-virgin olive oil in a 4-quart (4L) pot on medium-high and cook the yellow onions 5 minutes. Add the garlic for 1 minute, then the eggplant for 5 minutes more, stirring often so nothing sticks.", "Add the zucchini and red bell peppers, the tomatoes, the green beans, and the other teaspoon of kosher salt. Lower to medium-low and simmer 20 minutes.", "Peel and quarter the potatoes. When the vegetables are tender, add the potatoes and black pepper and cook 5 minutes. Take off the heat, stir in the basil, and serve hot, warm, or cold."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-033", "Lentil and Vegetable Dal", "American", ["section-book-plant-based"], "veg", "soup", 45, "Lentil dal gets a makeover with the addition of cauliflower and spinach.", [I("coconut oil", 2, "tbsp", "Pantry"), I("large yellow onion, finely chopped (1½ cups)", 1, "", "Produce"), I("finely chopped fresh ginger", 1, "tbsp", "Produce"), I("garlic, minced", 2, "cloves", "Produce"), I("vegetable stock", 6, "cups", "Pantry"), I("red lentils, picked over and rinsed", 1, "cups", "Pantry"), I("small head cauliflower, separated into florets and finely chopped (2 cups)", 0.3333, "", "Produce"), I("ground turmeric", 1, "tbsp", "Herbs & Spices"), I("ground coriander", 1, "tsp", "Herbs & Spices"), I("ground cumin", 0.5, "tsp", "Herbs & Spices"), I("ground cinnamon", 0.25, "tsp", "Herbs & Spices"), I("cayenne", 0.25, "tsp", "Herbs & Spices"), I("tomato paste", 2, "tbsp", "Pantry"), I("spinach, washed well, stemmed, and thinly sliced", 1, "bunch", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), IN("Juice of 1 medium lime (1 TB.)", 1, "", "Produce"), I("finely chopped fresh cilantro", 2, "tbsp", "Produce"), I("plant-based plain yogurt", 0.5, "cups", "Dairy & Eggs")], ["Warm the coconut oil in a large soup pot on medium-high. Cook the yellow onion, ginger, and garlic 5 minutes, stirring often and lowering the heat if needed so nothing burns.", "Pour in the vegetable stock and add the red lentils and cauliflower, then the cumin, coriander, turmeric, cinnamon, and cayenne. Let it come to a boil, then lower the heat and simmer 20 minutes.", "Once the lentils and cauliflower are soft, put the tomato paste in a small bowl, whisk in a ladle of the broth until smooth, and return it to the pot. Add the spinach with the lime juice, the kosher salt, and 1 tablespoon of the cilantro and simmer 5 minutes.", "Stir the rest of the cilantro into the yogurt and serve the dal warm with a spoonful on top."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-034", "Green Curry Vegetable Stew", "American", ["section-book-plant-based"], "veg", "bowl", 45, "There is something special about the fragrance and flavor of green curry spices, Kaffir lime, ginger, and coconut milk, and the bounty of vegetables in this dish is so good for you.", [I("virgin coconut oil", 2, "tbsp", "Pantry"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("(1- or 2-in.; 2.5 to 5cm) piece ginger, peeled and grated (1 or 2 TB.)", 1, "", "Produce"), I("Thai green curry paste", 2, "tbsp", "Pantry"), I("hot chile pepper, such as Serrano, seeded and thinly sliced", 1, "", "Produce"), I("medium yellow onion, halved and thinly sliced", 1, "", "Produce"), I("(8-oz.; 225g) pkg. shiitake mushrooms, stemmed and thinly sliced", 1, "", "Produce"), I("kosher salt, plus more to taste", 1, "tsp", "Herbs & Spices"), I("(14-oz.; 400g) can full-fat, best-quality Thai coconut milk", 1, "", "Pantry"), I("vegetable stock or water", 1, "cups", "Pantry"), I("Kaffir lime leaves, or 1 TB. grated lime zest", 2, "", "Produce"), I("carrot, thinly sliced", 1, "cups", "Produce"), I("large zucchini, halved and thinly sliced", 1, "", "Produce"), I("(10-oz.; 285g) pkg. baby spinach", 1, "", "Produce"), I("thinly sliced scallion, white and light green parts", 0.5, "cups", "Produce"), I("finely chopped fresh cilantro", 0.25, "cups", "Produce")], ["Melt the coconut oil in a large saucepan on medium-high. Add the garlic, ginger, green curry paste, and chile pepper and stir for 1 minute.", "Stir in the shiitake mushrooms and yellow onion with the kosher salt and cook 2 minutes longer.", "Pour in the coconut milk and vegetable stock and add the carrot and Kaffir lime leaves. Let it come to a boil, then simmer 5 minutes.", "Add the zucchini and simmer another 5 minutes.", "Add the spinach, scallion, and cilantro, cook 1 minute more, take off the heat, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-035", "Hearty Chili", "American", ["section-book-plant-based"], "veg", "bowl", 45, "I come from a family who loves chili, and making a pot on a snowy day is almost standard for us.", [I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("large yellow onions, diced (3 cups)", 2, "", "Produce"), I("medium red bell peppers, ribs and seeds removed, and diced", 4, "", "Produce"), I("medium yellow bell peppers, ribs and seeds removed, and diced", 2, "", "Produce"), I("(10-oz.; 285g) pkg. cremini (baby bella) mushrooms, thinly sliced", 1, "", "Produce"), I("garlic, finely chopped", 4, "cloves", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("chili powder", 2, "tbsp", "Herbs & Spices"), I("ground cumin", 1, "tsp", "Herbs & Spices"), I("Anaheim chile powder", 1, "tsp", "Herbs & Spices"), I("dried oregano", 1, "tsp", "Pantry"), I("freshly ground black pepper", 1, "tsp", "Herbs & Spices"), I("(28-oz.; 800g) cans diced tomatoes, with juice", 2, "", "Pantry"), I("(14-oz.; 400g) cans kidney beans, rinsed and drained", 2, "", "Pantry"), I("(14-oz.; 400g) cans black beans, rinsed and drained", 2, "", "Pantry"), I("habanero hot sauce, such as El Yucateco, plus more for serving", 1, "tbsp", "Pantry"), IN("Plant-based sour cream (optional)", 1, "", "Dairy & Eggs"), IN("Tortilla chips (optional)", 1, "", "Pantry")], ["Warm the extra-virgin olive oil in a large stockpot on medium. Cook the yellow onions and the red and yellow bell peppers for 10 minutes, stirring often.", "Add the cremini mushrooms and garlic, the chili powder and Anaheim chile powder, the cumin and oregano, and the kosher salt and black pepper. Cook 10 minutes, stirring often.", "Add the tomatoes and their juice and bring to a boil. Lower the heat to low or medium-low and let it bubble gently, uncovered, about 30 minutes until the peppers and onions are very soft.", "Stir in both kinds of beans with the habanero hot sauce and give it 5 minutes. Ladle into large bowls and top with sour cream and tortilla chips if you like."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-036", "Black-Eyed Pea Stew", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Celery, onion, and bell pepper, the Holy Trinity of Louisiana cooking, build the base of this tomato-rich Creole-style stew, with veggie Andouille sausage for protein.", [I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("large sweet onion, finely chopped (1½ cups)", 1, "", "Produce"), I("medium stalks celery, finely chopped (1 cup)", 3, "", "Produce"), I("large green bell pepper, ribs and seeds removed, and finely chopped (1 cup)", 1, "", "Produce"), I("veggie Andouille sausage, removed from casing (if necessary) and sliced or crumbled", 2, "links", "Pantry"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("Creole seasoning", 1, "tbsp", "Herbs & Spices"), I("kosher salt, plus more to taste", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper, plus more to taste", 0.5, "tsp", "Herbs & Spices"), I("(28-oz.; 800g) can diced tomatoes, with juice", 1, "", "Pantry"), I("dry red wine", 1, "cups", "Pantry"), I("(14-oz.; 400g) cans black-eyed peas, rinsed and drained", 2, "", "Pantry"), I("finely chopped fresh Italian flat-leaf parsley", 0.25, "cups", "Produce"), I("apple cider vinegar", 1, "tbsp", "Pantry"), I("Louisiana hot sauce, such as Crystal", 1, "tsp", "Pantry")], ["Warm the extra-virgin olive oil in a large saucepan on medium-high. Cook the sweet onion, celery, and green bell pepper for 5 minutes, stirring often and adjusting the heat as needed.", "Add the Andouille sausage and cook 2 minutes.", "Stir in the garlic and Creole seasoning with the kosher salt and black pepper for 1 minute.", "Add the tomatoes and their juice, red wine, and black-eyed peas. Lower the heat to medium and cook 10 minutes, stirring often.", "Once the vegetables are tender, take off the heat, stir in the hot sauce, apple cider vinegar, and parsley, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-037", "Jerusalem Artichoke Soup", "American", ["section-book-plant-based"], "veg", "soup", 45, "Jerusalem artichokes, or sunchokes, combine the nutty flavor of an artichoke with the creamy consistency of a potato, making them perfect for this comforting soup.", [I("virgin grapeseed oil or extra-virgin olive oil, plus more for garnish", 2, "tbsp", "Pantry"), I("medium yellow onions, chopped", 2, "", "Produce"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("(340g) Jerusalem artichokes, peeled or scrubbed well, and coarsely chopped", 12, "oz", "Pantry"), I("medium carrot, peeled and coarsely chopped", 1, "", "Produce"), I("kosher salt, plus more to taste", 0.5, "tsp", "Herbs & Spices"), I("hot vegetable stock", 5, "cups", "Pantry"), I("chopped fresh thyme leaves, or 1½ tsp. dried", 1, "tbsp", "Pantry"), IN("Large pinch (about 30 strands) saffron", 1, "", "Herbs & Spices"), IN("Juice of ½ medium lemon (2 TB.)", 1, "", "Produce"), I("freshly ground black pepper, or to taste", 0.25, "tsp", "Herbs & Spices")], ["Warm the grapeseed oil in a large soup pot on medium and cook the yellow onions 5 to 10 minutes, stirring often, until soft and translucent.", "Add the garlic and cook about 30 seconds until fragrant.", "Add the Jerusalem artichokes, carrot, and kosher salt. Cover, turn the heat to low, and cook 10 to 15 minutes, stirring often, until softened.", "Pour in the vegetable stock and add the thyme and saffron. Bring to a boil, then simmer 20 minutes until everything is soft.", "Let cool briefly, then blend smooth with a stick blender, or in batches in a countertop blender or food processor.", "Add the lemon juice, season with more kosher salt and the black pepper, and serve in warmed bowls with a thread of oil on top."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-038", "Posole", "American", ["section-book-plant-based"], "veg", "soup", 45, "This updated version of the traditionally long-simmered Mexican stew can be made in under half an hour, but it packs a huge punch of savory chile flavor.", [I("olive oil", 3, "tbsp", "Pantry"), I("large yellow onion, finely chopped (about 1½ cups)", 1, "", "Produce"), I("medium carrots, cut into ¼-in. (.5cm) rounds", 2, "", "Produce"), I("(8-oz.; 225g) pkg. cremini (baby bella) mushrooms, thinly sliced", 1, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("dried ground New Mexico chile powder", 3, "tbsp", "Pantry"), I("ground cumin", 1, "tsp", "Herbs & Spices"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("dried oregano", 0.5, "tsp", "Pantry"), I("vegetable stock", 4, "cups", "Pantry"), I("(15-oz.; 420g) can hominy, rinsed and drained", 1, "", "Pantry"), I("medium zucchini, trimmed, quartered lengthwise, and cut into ½-inch (1.25cm) chunks", 1, "", "Produce"), IN("Juice of 1 medium lime (1 TB.)", 1, "", "Produce"), I("finely chopped fresh cilantro", 2, "tbsp", "Produce")], ["Warm the olive oil in a large soup pot on medium-high and cook the yellow onion 5 minutes, stirring often and adjusting the heat as needed.", "Add the carrots and cremini mushrooms and cook 5 minutes.", "Add the garlic and stir 1 minute. Sprinkle in the cumin, oregano, New Mexico chile powder, and kosher salt and stir 30 seconds.", "Add the vegetable stock and let it simmer 5 minutes.", "Add the hominy and zucchini, bring to a boil, then lower to medium-low and cook 10 minutes.", "Take off the heat, add the lime juice and cilantro, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-039", "Celery Root Remoulade", "American", ["section-book-plant-based"], "veg", "green", 45, "Celery root, or celeriac, is grated and tossed in remoulade sauce for a quick, healthy, and delicious no-cook salad.", [IN("¼ cup plus 1 TB. plant-based mayo", 1, "", "Pantry"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("Dijon mustard", 2, "tbsp", "Pantry"), IN("Juice of 1 medium lemon (2 TB.)", 1, "", "Produce"), I("finely chopped cornichon pickles", 2, "tbsp", "Produce"), I("finely grated onion", 1, "tbsp", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 1, "tbsp", "Produce"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("(1½ lb.; 680g) celery root", 1, "", "Produce"), IN("Lettuce leaves or toast", 1, "", "Produce")], ["In a large bowl, whisk the mayo with the Dijon mustard and extra-virgin olive oil, then add the lemon juice, the cornichon pickles and grated onion, the parsley, and the kosher salt and black pepper. Keep to one side.", "Wash, peel, and quarter the celery root. Working fast so it does not brown, grate each piece straight into the dressing. Toss and serve at once on lettuce leaves or toast. Chilled, it keeps up to 2 days."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-040", "Roasted Tomato and White Bean Salad", "American", ["section-book-plant-based"], "veg", "green", 45, "Plum tomatoes are roasted until sweet and tossed with cannellini beans, red onion, and arugula for a healthy and flavorful salad.", [I("plum tomatoes, cored and halved lengthwise", 12, "", "Produce"), I("garlic, cut in very thin slices", 2, "cloves", "Produce"), I("olive oil", 3, "tbsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("(14-oz.; 400g) can cannellini beans, rinsed and drained", 1, "", "Pantry"), I("small red onion, very thinly sliced", 0.5, "", "Produce"), I("arugula, tough stems removed, washed, spun dry, and chilled", 1, "bunch", "Produce")], ["Heat the oven to 350°F (180°C).", "Set the plum tomato halves cut side up on a rimmed baking sheet and tuck 1 or 2 garlic slices into each. Drizzle with 1 tablespoon of the olive oil, season with the kosher salt and black pepper, and roast 40 minutes. Let cool a little.", "Toss the cannellini beans with the other 2 tablespoons olive oil, the red onion, and the arugula in a medium bowl.", "Divide among 4 chilled plates, top with the roasted tomatoes and their pan juices, and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-041", "Picnic Potato Salad", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Tender new potatoes are bathed in a sauce of mayo, herbs, and lots of crunchy celery and dill pickles in this perfect potato salad.", [I("(1.5kg) small new (red) potatoes", 3, "lb", "Produce"), I("plant-based mayo", 0.75, "cups", "Pantry"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("whole-grain Dijon mustard", 2, "tbsp", "Pantry"), I("apple cider vinegar", 2, "tbsp", "Pantry"), I("finely chopped fresh dill", 2, "tbsp", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("hot sauce, such as Crystal or Tabasco", 1, "tsp", "Pantry"), I("kosher salt", 1.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("medium red onion, finely chopped", 1, "", "Produce"), I("medium stalks celery, finely chopped (1½ cups)", 4, "", "Produce"), I("finely chopped dill pickle", 0.5, "cups", "Produce")], ["Bring 2 inches (5cm) of water to a boil on medium-high in a pot with a tight lid. Steam the potatoes in a steamer basket about 10 minutes, until a fork slides in easily. Tip them into a wide colander and leave 15 minutes to drain and cool.", "Meanwhile, whisk the mayo, extra-virgin olive oil, mustard, apple cider vinegar, dill and parsley, the hot sauce, and the kosher salt and black pepper in a large bowl until smooth. Set aside a quarter of this dressing in a small bowl.", "Once cool enough to handle, cut the potatoes into halves or quarters.", "Fold the red onion, celery, and dill pickle into the dressing in the large bowl, then gently fold in the potatoes. Chill the salad and the reserved dressing for 1 hour.", "Fold in the reserved dressing just before serving. Keeps up to 3 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-042", "Warm Lentil, Barley, and Sweet Potato Salad", "American", ["section-book-plant-based"], "veg", "soup", 45, "Warm lentils, barley, and roasted sweet potatoes tossed in a pomegranate and Dijon mustard dressing, then finished with bright pomegranate seeds.", [I("small green (du Puy) lentils", 0.5, "cups", "Pantry"), I("pearl barley", 0.5, "cups", "Pantry"), I("garlic, lightly smashed", 1, "cloves", "Produce"), I("bay leaf", 1, "", "Herbs & Spices"), I("large sweet potato, peeled and cut in 1-in. (2.5cm) dice", 1, "", "Produce"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce"), I("small shallot, finely chopped", 1, "", "Produce"), I("pomegranate molasses", 1, "tbsp", "Produce"), I("Dijon mustard", 1, "tbsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), IN("Seeds from 1 pomegranate", 1, "", "Produce")], ["Put the lentils, pearl barley, garlic, and bay leaf in a medium saucepan and add water to come 2 inches (5cm) above them. Let it boil, then cook on medium-low for 40 minutes until tender. Drain, discard the bay leaf, and let cool slightly.", "Meanwhile, heat the oven to 400°F (200°C). Toss the sweet potato with 1 tablespoon of the extra-virgin olive oil on a parchment-lined baking sheet and roast 30 minutes, stirring once. Let cool slightly.", "Whisk the shallot with the lemon juice, the Dijon mustard and pomegranate molasses, and the kosher salt and black pepper in a small bowl, then whisk in the remaining 2 tablespoons olive oil in a thin stream.", "Gently combine the lentils, barley, and sweet potato in a wide serving bowl and toss with half the dressing. Scatter the pomegranate seeds on top, spoon over the rest of the dressing, and serve warm."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-043", "Red Cabbage with Apples and Pecans", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Lightly pickled red onions pair perfectly with just-cooked red cabbage and apple with a toasty pecan topping.", [I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("large red onion, halved and thinly sliced (1½ cups)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("apple cider vinegar", 0.25, "cups", "Pantry"), I("whole-grain Dijon mustard", 1, "tsp", "Pantry"), I("large, crisp apple, such as Fuji, skin on, cored, and thinly sliced", 1, "", "Produce"), I("small red cabbage, cored, quartered, and thinly sliced (about 5 cups)", 1, "", "Produce"), IN("1 or 2 TB. water", 1, "", "Pantry"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("toasted, chopped pecans", 0.5, "cups", "Pantry")], ["Warm the extra-virgin olive oil in a large nonstick sauté pan on medium-high. Cook the red onion with the kosher salt for 4 or 5 minutes, stirring often, until limp.", "Turn the heat to medium and take the pan off the burner for roughly 30 seconds. Add the apple cider vinegar and mustard to coat the onion, then return to the heat for 30 seconds to 1 minute more, letting it reduce slightly.", "Add the apple and red cabbage, plus 1 tablespoon water if it looks dry. Cover and cook on medium for 5 minutes, giving it a stir once or twice and splashing in more water if needed.", "Uncover and keep cooking, stirring, until the cabbage is crisp-tender. Season with the black pepper, scatter the pecans over, and serve hot, warm, or cold."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-044", "Stir-Fried Chinese Cress with Fermented Black Beans", "American", ["section-book-plant-based"], "veg", "skillet", 45, "The bitter flavor of Chinese watercress is a perfect foil to the deeply umami flavor of fermented black beans and a kick of garlic.", [I("grapeseed oil", 2, "tbsp", "Pantry"), I("garlic, very thinly sliced", 8, "cloves", "Produce"), I("grated fresh ginger", 1, "tbsp", "Produce"), I("bunches Chinese watercress, washed well, bottom 1 in. (2.5cm) of stem removed (about 12 cups)", 4, "", "Pantry"), I("vegetable stock", 0.25, "cups", "Pantry"), I("fermented black beans", 0.5, "cups", "Pantry"), I("crushed red pepper flakes", 0.5, "tsp", "Herbs & Spices")], ["Get a wok or large cast-iron skillet hot on medium. Add the grapeseed oil, garlic, and ginger and stir-fry 30 seconds.", "Add the Chinese watercress and toss for 30 seconds.", "Add the vegetable stock, fermented black beans, and red pepper flakes and stir-fry 1 or 2 minutes more, until the beans are hot and the cress is tender. Serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-045", "Roasted Tomatoes", "American", ["section-book-plant-based"], "veg", "green", 45, "Small tomatoes become sweet, with a concentrated tomato flavor, when roasted slowly with garlic, salt, and olive oil.", [I("(1kg) cherry tomatoes, halved", 2, "lb", "Produce"), I("garlic, sliced very thin", 3, "cloves", "Produce"), I("olive oil", 2, "tbsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Heat the oven to 300°F (150°C) with two racks set in the lower third.", "Spread the cherry tomato halves cut side up over 2 rimmed baking sheets. Push a garlic slice into each half, drizzle with the olive oil, and sprinkle lightly with the kosher salt and black pepper.", "Bake about 1 hour, stirring once or twice, until shrunken and very soft. Serve it warm or at room temperature; leftovers keep up to 3 days chilled."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-046", "Herbed Zucchini", "American", ["section-book-plant-based"], "veg", "skillet", 45, "Tender slices of zucchini are brushed with plant-based mayo and encrusted with panko, fresh herbs, and olive oil for a lower-fat version of a fried favorite.", [I("large (about 8-in.; 20cm) zucchini", 2, "", "Produce"), I("plant-based mayonnaise", 0.25, "cups", "Pantry"), I("panko breadcrumbs", 2, "cups", "Pantry"), I("finely chopped fresh mixed herbs such as parsley, chives, chervil, and/or tarragon", 0.5, "cups", "Produce"), I("extra-virgin olive oil", 0.5, "cups", "Pantry"), I("kosher salt", 2, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 1, "tsp", "Herbs & Spices"), I("lemon zest", 2, "tsp", "Produce")], ["Heat the oven to 400°F (200°C) and line a baking sheet with parchment.", "Trim the zucchini and cut into ¼-inch (.5cm) rounds. Blot the rounds dry on paper towels, then brush each one on both sides with the mayonnaise.", "Mix the panko and herbs with the lemon zest, the extra-virgin olive oil, and the kosher salt and black pepper in a small, shallow bowl.", "Press each zucchini round into the crumbs to coat both sides and lay on the baking sheet.", "Bake 20 minutes, flipping carefully with a spatula halfway through, and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-047", "Sautéed Broccoli Rabe", "American", ["section-book-plant-based"], "veg", "skillet", 45, "Broccoli rahe is a slightly hitter cruciferous vegetable that's incredibly flavorful when prepared with garlic and olive oil.", [I("large bunch broccoli rabe, about 1 lb. (450g)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("garlic, thinly sliced", 3, "cloves", "Produce"), I("crushed red pepper flakes", 0.5, "tsp", "Herbs & Spices")], ["Wash the broccoli rabe and cut about ½ inch (1.25cm) off the tough stem ends.", "Bring a medium saucepan of water to a boil on high, enough to cover the broccoli rabe by 1 inch (2.5cm). Add ½ teaspoon of the kosher salt and the broccoli rabe, blanch 1 minute, then chill it in ice water, drain, and set aside.", "Warm the extra-virgin olive oil with the garlic in a medium sauté pan on medium. As soon as the garlic sizzles and turns pale gold, add the broccoli rabe, toss, and cook 5 minutes, stirring often, until tender.", "Season with the rest of the kosher salt and the red pepper flakes and serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-048", "Southern-Style Braised Greens", "American", ["section-book-plant-based"], "veg", "soup", 45, "Nutritious greens are slowly braised until tender in flavorful vegetable stock seasoned with olive oil, garlic, onions, and a little smoked sea salt.", [I("vegetable stock", 4, "cups", "Pantry"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("smoked sea salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("garlic, crushed and finely chopped", 2, "cloves", "Produce"), I("large bunch collard greens, tough stems removed, cut in small pieces", 1, "", "Produce"), I("large bunch mustard greens, tough stems removed, cut in small pieces", 1, "", "Produce"), I("large bunch curly kale, tough stems removed, cut in small pieces", 1, "", "Produce"), I("apple cider vinegar, or juice of ½ lemon (1 TB.)", 1, "tbsp", "Pantry")], ["Combine the vegetable stock and garlic with the extra-virgin olive oil, the smoked sea salt, and the black pepper in a large saucepan or soup pot on high and bring to a boil.", "Add the collard greens, mustard greens, and kale. Lower the heat to medium and cook uncovered about 35 minutes, stirring now and then and keeping it at a gentle simmer, until tender.", "Season with the apple cider vinegar and serve with some of the cooking liquid spooned over."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-049", "Fried Green Tomatoes", "American", ["section-book-plant-based"], "veg", "skillet", 45, "Unripe green tomatoes are dredged in cornmeal and quickly fried for a delicious classic born of the desire not to waste food.", [I("large, green beefsteak tomatoes", 4, "", "Produce"), I("unsweetened soy milk", 0.5, "cups", "Dairy & Eggs"), IN("Juice of ½ lemon (1 TB.)", 1, "", "Produce"), I("fine cornmeal", 1.25, "cups", "Pantry"), IN("Grapeseed oil", 1, "", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Core the beefsteak tomatoes, trim 1/8 inch (3mm) from each end, and cut each into 5 even slices.", "Whisk the soy milk and lemon juice in a medium bowl and leave a few minutes to curdle.", "Spread the cornmeal on a rimmed plate.", "Heat ½ inch (1.25cm) grapeseed oil in a large frying pan on medium-high until shimmering.", "In batches that fit easily in the pan, dip each slice in the soy milk mixture, then coat in cornmeal. Fry about 2 minutes, adjusting the heat so they do not burn, flip carefully, and fry 2 minutes more. Drain on a plate lined with paper towels, sprinkle with the kosher salt and black pepper, and hold them somewhere warm. Change the oil if the cornmeal starts to burn. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-050", "Almond and Breadcrumb-Stuffed Piquillo Peppers", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Tangy piquillo peppers are stuffed with a savory almond and breadcrumb filling.", [I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("small shallot, finely chopped", 1, "", "Produce"), I("crushed red pepper flakes", 0.5, "tsp", "Herbs & Spices"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("fresh breadcrumbs", 1, "cups", "Pantry"), I("finely chopped Marcona almonds", 0.5, "cups", "Pantry"), I("salted capers, rinsed, drained, and finely chopped", 1, "tbsp", "Pantry"), I("(14-oz.; 400g) can piquillo peppers, drained", 1, "", "Pantry")], ["Heat the oven to 350°F (180°C).", "Warm 1 tablespoon of the extra-virgin olive oil in a small saucepan on medium-high. Cook the garlic, shallot, and red pepper flakes for 30 seconds, then stir in the parsley and take off the heat.", "Mix the breadcrumbs, Marcona almonds, capers, and garlic mixture in a small bowl and stir in another tablespoon of the olive oil.", "Drizzle a medium baking dish with half the remaining oil (about 1 teaspoon). Stuff each piquillo pepper with roughly 1 tablespoon of filling and set in the dish. Drizzle with the last of the oil and bake 20 minutes. Serve the peppers hot, warm, or at room temperature."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-051", "Sautéed Mushroom Medley", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Sautéed mushrooms are so versatile—have them as a side dish, toss them with pasta, spread them on toasted French bread for crostini .", [I("(14g) dried porcini mushrooms", 0.5, "oz", "Pantry"), I("boiling water", 0.5, "cups", "Pantry"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("shallots, finely chopped (¼ cup)", 2, "", "Produce"), I("garlic, minced", 3, "cloves", "Produce"), I("(8-oz.; 225g) pkg. cremini (baby bella) mushrooms, thinly sliced", 1, "", "Produce"), I("(8-oz.; 225g) pkg. white button mushrooms, thinly sliced", 1, "", "Produce"), I("(4-oz.; 110g) pkg. shiitake mushrooms, stemmed and thinly sliced", 1, "", "Produce"), I("chopped fresh rosemary or ½ tsp. dried", 1, "tsp", "Pantry"), I("chopped fresh thyme or ½ tsp. dried", 1, "tsp", "Pantry"), I("kosher salt, or to taste", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper, or to taste", 0.5, "tsp", "Herbs & Spices"), I("dry white wine", 2, "tbsp", "Pantry"), I("finely chopped fresh Italian flat-leaf parsley", 0.25, "cups", "Produce")], ["Put the porcini mushrooms in a small bowl, cover with the boiling water, and soak about 5 minutes until soft. Lift them out, swishing off any grit, chop, and set aside. Keep the soaking liquid.", "Warm the extra-virgin olive oil in a large sauté pan on medium-high. Cook the shallots and garlic 2 minutes, stirring the whole time and turning the heat down if they threaten to burn.", "Add the porcini, cremini, white button, and shiitake mushrooms with the rosemary and thyme. Cook 10 minutes, stirring now and then, until they start to brown.", "Season with the kosher salt and black pepper, turn the heat to high, and cook 3 to 5 minutes more, stirring often, until deep golden with bits catching on the pan.", "Strain in the soaking liquid, holding back the last gritty teaspoons, and add the white wine. Scrape the pan hard to lift the browned bits and cook until the liquid is gone.", "Off the heat, toss in the parsley, adjust the salt and pepper, and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-052", "Sesame Ginger Broccoli", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Broccoli is quickly blanched to preserve its green color and crunch and then flavored with garlic and singer for a simple, perfectly spiced plate of veggies.", [I("large head fresh broccoli", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("light sesame oil", 2, "tbsp", "Pantry"), I("garlic, thinly sliced", 2, "cloves", "Produce"), I("freshly grated ginger", 1, "tsp", "Produce"), I("gomasio", 1, "tsp", "Pantry")], ["Wash the broccoli and break it into small florets. Peel the stem and cut it into ¼-inch (.5cm) coins. Set up a bowl of ice water.", "Set a medium pot of water on high, let it boil, and add the kosher salt.", "Blanch the florets and stem pieces for 2 minutes, just until crisp-tender, then lift them straight into the ice water with tongs. Drain and set aside.", "Warm the sesame oil in a large sauté pan on medium-high. Add the garlic and ginger and stir 1 minute.", "Add the broccoli and cook 2 minutes.", "Scatter the gomasio over and serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-053", "Stuffed Mushrooms", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Aromatic vegetables, herbs, and mushroom stems are sauteed in plenty of olive oil; mixed with crunchy panko breadcrumbs; and baked in mushroom caps.", [I("extra-virgin olive oil", 5, "tbsp", "Pantry"), I("(10-oz.; 285g) pkg. white button mushrooms", 2, "", "Produce"), I("small red bell pepper, ribs and seeds removed, and finely chopped", 0.25, "", "Produce"), I("small shallots, finely chopped", 2, "", "Produce"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("dry white wine", 4, "tbsp", "Pantry"), I("panko breadcrumbs", 0.5, "cups", "Pantry"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("dried thyme", 1, "tsp", "Pantry"), I("dried oregano", 0.5, "tsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Heat the oven to 400°F (200°C). Then brush a baking dish that just fits the mushrooms with 1 tablespoon of the extra-virgin olive oil.", "Twist the stems out of the mushroom caps and set the caps in the dish. Chop the stems finely.", "Warm 2 tablespoons of the olive oil in a medium sauté pan on medium-high. Cook the chopped stems, red bell pepper, shallots, and garlic about 5 minutes until the mushrooms start to brown.", "Add 1 tablespoon of the white wine and scrape the pan. Mix in the panko and parsley, the thyme and oregano, and the kosher salt and black pepper, then take off the heat.", "Pour the other 3 tablespoons wine into the dish around the caps. Spoon the filling loosely into each cap and drizzle with the last 2 tablespoons olive oil.", "Bake 20 minutes, until the mushrooms are tender and the tops golden. Serve it hot, warm, or at room temperature."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-054", "Minted Peas and Baby Potatoes", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Sweet peas and tender new potatoes are tossed in a simple dressing of olive oil and fresh mint.", [I("(450g) very small new potatoes", 1, "lb", "Produce"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("shallot, thinly sliced (¼ cup)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("shelled fresh peas, or 1 (10-oz.; 285g) pkg. frozen peas, thawed", 4, "cups", "Produce"), I("water", 2, "tbsp", "Pantry"), I("finely chopped fresh mint", 2, "tbsp", "Produce"), IN("Juice of ½ lemon (1 TB.)", 1, "", "Produce"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Bring 1 inch (2.5cm) of water to a boil on medium in a large pot with a tight lid. Steam the potatoes in a steamer basket about 10 minutes until a fork slides in easily. Drain, let cool a little, and halve any bigger than 1 inch (2.5cm).", "Meanwhile, warm the extra-virgin olive oil in a large saucepan on medium-high and cook the shallot with the kosher salt about 5 minutes until soft.", "Add the peas and water and cook 2 minutes.", "Add the potatoes, turn the heat to high, and toss for 1 minute. Off the heat, stir in the lemon juice, black pepper, and mint and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-055", "Sesame Asparagus", "American", ["section-book-plant-based"], "veg", "roast", 45, "This recipe contains just a few ingredients but boasts huge flavor.", [I("(450g) slender asparagus spears", 1, "lb", "Pantry"), I("dark sesame oil", 1, "tbsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("toasted sesame seeds or gomasio", 1, "tbsp", "Pantry")], ["Get the oven heated to 400°F (200°C), or fire up a grill for direct, high heat. For the oven, line a baking sheet with parchment.", "Bend one asparagus spear until the woody base snaps off, then cut the rest to the same length and peel the bottom third of each stem. Spread on the baking sheet and toss with the sesame oil, kosher salt, and black pepper.", "Roast for 8 minutes, or grill about 5 minutes on direct, turning once or twice, until just tender and a spear bends slightly when lifted. Serve hot, warm, or cold, topped with the sesame seeds."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-056", "Roasted Root Vegetable Medley", "American", ["section-book-plant-based"], "veg", "roast", 45, "For this satisfying pan of root vegetables accented with fresh herbs and plenty of olive oil, choose a mix of carrots, celery root, potatoes, rutabaga, turnips, and parsnips.", [I("assorted root vegetables, peeled and cut into 1-in. (2.5cm) chunks", 6, "cups", "Pantry"), I("extra-virgin olive oil", 0.5, "cups", "Pantry"), I("finely chopped fresh rosemary", 1, "tsp", "Herbs & Spices"), I("fresh thyme leaves", 1, "tsp", "Herbs & Spices"), I("fresh sage, finely chopped", 1, "tsp", "Herbs & Spices"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Heat the oven to 400°F (200°C).", "Spread the root vegetables out in a glass 9x13-inch (23x33cm) baking pan, pour the extra-virgin olive oil over, and add the herbs (rosemary, thyme, and sage) and the kosher salt and black pepper. Toss well with your hands.", "Roast uncovered for 35 to 40 minutes, stirring once or twice, until tender and browned at the edges. Serve hot or warm."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-057", "Southern Sweet Potatoes with Pecan Streusel", "American", ["section-book-plant-based"], "veg", "bowl", 45, "with Pecan Streusel (T) Creamy sweet potatoes are spiced with a touch of cinnamon and adorned with a sweet and savory pecan streusel topping in this classic casserole.", [I("(450g) sweet potatoes, peeled and cut into 2-in. (5cm) chunks", 2, "lb", "Produce"), IN("2 TB. plus ¼ cup plant-based butter", 1, "", "Dairy & Eggs"), IN("2 TB. plus ¼ cup brown sugar, lightly packed", 1, "", "Pantry"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("all-purpose flour", 0.25, "cups", "Pantry"), I("chopped walnuts", 0.25, "cups", "Pantry"), IN("Pinch cayenne", 1, "", "Herbs & Spices")], ["Heat the oven to 350°F (180°C). Then line a baking sheet with parchment and lightly grease an 8x8-inch (20x20cm) baking pan.", "Bring 1 inch (2.5cm) of water to a boil on medium-high in a large pot that has a steamer basket in it. Steam the sweet potatoes, covered, for 10 minutes until tender, then let cool slightly.", "Mash the sweet potatoes smooth in a medium bowl and mix in 2 tablespoons each of the butter and brown sugar, plus the cinnamon, kosher salt, and black pepper. Spread evenly in the baking pan.", "For the topping, combine the all-purpose flour, the remaining ¼ cup brown sugar, the walnuts, and the cayenne in a medium bowl.", "Dot the remaining ¼ cup butter over the flour mixture in small pieces and rub it in with your fingers until it clumps. Scatter over the sweet potatoes and bake about 20 minutes until golden. Serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-058", "Winter Vegetable Pot Pie", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Lots of herh-seasoned veggies in a creamy sauce make this vegetable pot pie a comfort food favorite.", [I("grapeseed oil", 4, "tbsp", "Pantry"), I("all-purpose flour", 3, "tbsp", "Pantry"), I("Golden Chicken-y Stock", 3, "cups", "Pantry"), I("large yellow onion, cut in small dice (1½ cups)", 1, "", "Produce"), I("large stalks celery, cut in small dice (about 2 cups)", 4, "", "Produce"), I("medium carrots, cut in small dice (2 cups)", 3, "", "Produce"), I("(10-oz.; 285g) pkg. cremini (baby bella) mushrooms, quartered", 1, "", "Produce"), I("garlic, minced", 3, "cloves", "Produce"), I("large red-skin potatoes, cut in small dice (about 2 cups)", 4, "", "Produce"), I("medium sweet potato, cut in small dice (about 1 cup)", 1, "", "Produce"), I("frozen lima beans", 2, "cups", "Frozen"), I("bay leaf", 1, "", "Herbs & Spices"), I("dried thyme", 1, "tsp", "Pantry"), I("kosher salt, plus more to taste", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("sheet puff pastry, thawed", 1, "", "Frozen")], ["Heat the oven to 400°F (200°C).", "Warm 2 tablespoons of the grapeseed oil in a small saucepan on medium. Whisk in the all-purpose flour and cook about 2 minutes, stirring constantly, until pale gold and toasty-smelling.", "Whisk in 2 cups of the Golden Chicken-y Stock and simmer 5 minutes. Set the sauce aside off the heat.", "Warm the remaining 2 tablespoons oil in a wide sauté pan on medium-high. Cook the yellow onion and garlic with the carrots, celery, and cremini mushrooms about 10 minutes, stirring often and adjusting the heat, until soft and lightly colored.", "Add the last cup of stock with the potatoes, sweet potato, lima beans, thyme and bay leaf, and the kosher salt and black pepper. Put the lid on and cook 10 minutes, stirring once or twice and adding a splash of water if it looks dry.", "Take out the bay leaf, stir in the reserved sauce, and spoon everything into a 9x13-inch (23x33cm) baking dish.", "On a floured surface, roll the puff pastry to cover the dish with a ½-inch (1.25cm) overhang. Prick it all over with a fork, lay it over the filling, and tuck the edges down inside the dish.", "Bake about 30 minutes, until the pastry is puffed and the filling bubbles. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-059", "Bisteeya (Moroccan Phyllo Pie)", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Bisteeya, also known as pastille, is a dish of Berber origins often served at the beginning of a celebratory Moroccan meal.", [I("extra-virgin olive oil", 6, "tbsp", "Pantry"), I("large red onions, finely chopped (3 cups)", 2, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("grated fresh ginger", 1, "tbsp", "Produce"), I("small hot green chile, seeded and finely chopped", 1, "", "Produce"), I("ground cinnamon, plus more for dusting", 1, "tsp", "Herbs & Spices"), I("saffron threads, crushed", 0.5, "tsp", "Herbs & Spices"), I("Golden Chicken-y Stock", 1, "cups", "Pantry"), I("(14-oz.; 400g) cans chickpeas, rinsed and drained", 2, "", "Pantry"), I("russet potato, peeled and finely chopped (1½ cups)", 1, "", "Produce"), I("preserved lemon, peel only, finely chopped", 1, "", "Produce"), I("finely chopped fresh cilantro", 2, "tbsp", "Produce"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("blanched almonds", 1, "cups", "Pantry"), I("confectioners’ sugar, plus more for dusting", 1, "tbsp", "Pantry"), I("(9×14-in.; 23×35.5cm) sheets phyllo dough", 6, "", "Frozen")], ["Heat the oven to 400°F (200°C) and line a baking sheet with parchment.", "Warm 2 tablespoons of the extra-virgin olive oil in a wide sauté pan on medium-high. Cook the red onions, garlic, ginger, and green chile for 10 minutes, stirring often.", "Add ½ teaspoon of the cinnamon, the saffron, and the Golden Chicken-y Stock and let it come to a boil. Add the chickpeas, russet potato, and preserved lemon peel, lower to medium, and cook about 10 minutes, stirring often, until the potato is very soft and most of the liquid has cooked off.", "Mix in the cilantro, kosher salt, and black pepper and leave to cool.", "Toast the almonds on the lined baking sheet in the oven for 6 minutes, then let cool.", "Pulse the almonds with the rest of the cinnamon and the confectioners' sugar in a food processor until finely ground.", "Oil a 9-inch (23cm) round cake pan. Lay in one sheet of phyllo dough and sprinkle with a sixth of the almond mixture. Brush the next sheet with oil and lay it across the first, oiled side up, and add more almond mixture. Keep layering phyllo and almonds, turning each sheet so the overhang spreads evenly around the pan. Fill with the chickpea mixture, fold the overhanging phyllo over the top, and brush with a little more oil.", "With a rimmed baking sheet underneath, bake the pie about 35 minutes until crisp and golden. Let cool slightly, ease the pie out of the pan, dust with more confectioners' sugar and cinnamon, and cut into wedges."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-060", "Savory Stuffed Cabbage", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Cabbage rolls are incredibly flavorful Eastern European comfort food.", [I("large napa cabbage leaves, bottom 3 in. (7.5cm) of stem removed, frozen for at least 1 hour", 12, "", "Produce"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("small yellow onion, finely chopped (¾ cup)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("(8-oz.; 225g) pkg. cremini (baby bella) mushrooms, finely chopped", 1, "", "Produce"), I("finely chopped fresh dill", 1, "tbsp", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 1, "tbsp", "Produce"), I("dried thyme leaves", 0.5, "tsp", "Pantry"), I("cooked brown rice", 1, "cups", "Pantry"), I("vegetable stock", 2, "cups", "Pantry"), I("tomato paste", 4, "tbsp", "Pantry"), I("sugar", 2, "tbsp", "Pantry"), I("ground allspice", 0.5, "tsp", "Herbs & Spices"), I("dry white wine", 0.25, "cups", "Pantry")], ["Heat the oven to 400°F (200°C) and lightly grease a 9x13-inch (23x33cm) glass baking pan.", "Let the frozen napa cabbage leaves thaw at room temperature, squeeze out the water, and lay them on paper towels.", "Warm the extra-virgin olive oil in a large sauté pan on medium-high and cook the yellow onion with the kosher salt and black pepper for 2 minutes, stirring.", "Stir in the cremini mushrooms and keep stirring often until they color. Off the heat, mix in the dill, parsley, thyme, and brown rice.", "Bring the vegetable stock and white wine to a boil with the tomato paste, allspice, and sugar in a small saucepan on medium-high. Lower to medium and cook about 10 minutes, stirring, until slightly reduced and thickened. Keep warm.", "Spoon a few tablespoons of filling onto the middle of each leaf, fold in the short sides, and roll into a snug log. Lay the rolls in the baking pan.", "Pour the sauce over, cover tightly with heavy-duty foil, and bake 30 minutes. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-061", "Mushroom Lasagna", "American", ["section-book-plant-based"], "veg", "bowl", 45, "The meaty flavor of mushrooms blends perfectly with Cashew Ricotta and zesty Tomato Sauce.", [I("(14g) dried porcini mushrooms", 0.5, "oz", "Pantry"), I("boiling water", 0.5, "cups", "Pantry"), I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("garlic, minced", 3, "cloves", "Produce"), I("(8-oz.; 225g) pkg. cremini (baby bella) mushrooms, thinly sliced", 1, "", "Produce"), I("(4-oz.; 110g) pkg. shiitake mushrooms, stemmed and thinly sliced", 1, "", "Produce"), I("chopped fresh rosemary or ½ tsp. dried", 1, "tsp", "Pantry"), I("kosher salt, or to taste", 1, "tsp", "Herbs & Spices"), I("dried oregano", 0.5, "tsp", "Pantry"), I("freshly ground black pepper, or to taste", 0.5, "tsp", "Herbs & Spices"), I("dry red wine", 0.25, "cups", "Pantry"), I("Tomato Sauce", 4, "cups", "Pantry"), I("no-boil lasagna noodles", 9, "", "Pantry"), I("Cashew Ricotta", 2, "cups", "Pantry")], ["Heat the oven to 375°F (190°C) and lightly grease a 9x13-inch (23x33cm) baking dish.", "Soak the porcini mushrooms in the boiling water in a small bowl for about 5 minutes. Lift them out, swishing off any grit, chop, and set aside. Keep the soaking liquid.", "Warm the extra-virgin olive oil in a large sauté pan on medium-high and cook the garlic 1 minute, stirring constantly.", "Add the porcini, cremini, and shiitake mushrooms with the rosemary, kosher salt, oregano, and black pepper. Cook 10 minutes, stirring now and then, until browning.", "Strain in the soaking liquid, leaving the gritty last few teaspoons behind, add the red wine, and scrape up the pan. Cook until the liquid is gone, then set aside.", "Spread 1 cup of the Tomato Sauce over the bottom of the dish and lay 3 lasagna noodles on top. Add half the mushrooms and half the Cashew Ricotta, then ½ cup sauce. Repeat with 3 noodles, the rest of the mushrooms and ricotta, and 1 cup sauce. Top with the last 3 noodles and 1 cup sauce. Cover with heavy-duty foil, leaving one corner open to vent. Keep the last ½ cup sauce for serving.", "Bake 50 minutes until bubbling. Let rest 5 minutes before slicing, and serve with the reserved sauce, warmed."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-062", "Summer Squash and Onion Bake", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Tender zucchini and yellow summer squash slices are bathed in a creamy bechamel sauce with plenty of sweet onions and then topped with breadcrumbs and baked until golden.", [I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("large sweet onions, such as Vidalia, thinly sliced into rings", 2, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("medium zucchini, thinly sliced", 2, "", "Produce"), I("medium yellow squash, thinly sliced", 2, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("all-purpose flour", 2, "tbsp", "Pantry"), I("nondairy milk, such as rice or soy", 1.5, "cups", "Pantry"), I("ground nutmeg", 0.25, "tsp", "Herbs & Spices"), I("finely chopped fresh rosemary", 0.5, "tsp", "Herbs & Spices"), I("panko breadcrumbs", 1, "cups", "Pantry"), I("finely chopped fresh chives", 2, "tbsp", "Produce"), I("dried thyme", 1, "tsp", "Pantry")], ["Heat the oven to 350°F (180°C) and lightly grease an 8x8-inch (20x20cm) baking dish.", "Warm 2 tablespoons of the extra-virgin olive oil in a wide sauté pan on medium-high and cook the sweet onions 5 minutes, stirring, until soft.", "Add the garlic and stir 1 minute. Scoop the onions and garlic out of the pan and keep warm.", "Add 1 tablespoon more oil to the pan with the zucchini and yellow squash and season with the kosher salt and black pepper. Turn the heat to high and cook 5 minutes, stirring every minute or so, until they start to turn golden.", "Sprinkle in the all-purpose flour, lower the heat to medium, and stir 1 minute. Return the onions to the pan.", "Stir in the nondairy milk with the rosemary and nutmeg, let it boil, and cook about 2 minutes until thickened. Take off the heat.", "Mix the panko, chives, thyme, and the last tablespoon of oil in a small bowl.", "Spread the squash mixture in the baking dish, cover evenly with the crumbs, and bake uncovered for 30 minutes. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-063", "Roasted Tomato Polenta Lasagna", "American", ["section-book-plant-based"], "veg", "dessert", 45, "It takes some time to assemble this dish, but the savory flavors of roasted eggplant, tomatoes, pesto, toasted pine nuts, and creamy polenta are worth it.", [I("water", 5, "cups", "Pantry"), I("coarse polenta (not instant)", 1, "cups", "Pantry"), I("kosher salt", 1.5, "tsp", "Herbs & Spices"), I("large Italian eggplant, cut in 1-in. (2.5cm) cubes", 1, "", "Produce"), I("(340g) cherry tomatoes, halved", 12, "oz", "Produce"), I("garlic, thinly sliced", 3, "cloves", "Produce"), I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("Tomato Sauce", 1.5, "cups", "Pantry"), I("Summer Pesto", 1, "cups", "Pantry"), I("large basil leaves, cut in thin ribbons (chiffonade)", 6, "", "Produce"), I("pine nuts, toasted", 0.5, "cups", "Pantry")], ["Use parchment to line a 9x9-inch (23x23cm) baking pan, then brush with a little of the olive oil.", "Bring the water to a boil in a large saucepan on high. Pour in the polenta in a slow stream, stirring all the time, and add ½ teaspoon of the kosher salt. Lower the heat to medium and keep stirring until fully cooked, creamy, and smooth.", "Pour the polenta into the lined pan and let it cool a little, then cover and chill at least 2 hours or overnight until firm.", "Heat the oven to 400°F (200°C).", "Salt the eggplant with ½ teaspoon kosher salt and drain in a colander for 30 minutes. Rinse and squeeze gently.", "Toss the eggplant and cherry tomatoes with the garlic and 3 tablespoons of the olive oil on a large rimmed baking sheet. Roast 30 minutes, stirring once or twice. Take out and lower the oven to 375°F (190°C).", "Turn the set polenta out of the pan, cut it into thirds, and split each third horizontally into 3 thin slabs for 9 pieces. Use a spatula; broken pieces can be patched together in the pan.", "Brush the pan with the last tablespoon of olive oil. Spread ½ cup Tomato Sauce on the bottom and cover with 3 polenta slabs. Add half the roasted vegetables and half the Summer Pesto, then another polenta layer. Repeat with ½ cup sauce and the rest of the vegetables and pesto, finish with polenta, and spread the remaining sauce on top. Cover and bake about 40 minutes until bubbling.", "Scatter the basil and pine nuts over just before serving hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-064", "Tamale Casserole", "American", ["section-book-plant-based"], "veg", "roast", 45, "A tender crust of cornmeal and masa harina encloses a slightly spicy, savory filling of veggies and pinto beans in this lighter version of a tamale casserole.", [I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("large yellow onion, finely chopped (1½ cups)", 1, "", "Produce"), I("medium green bell pepper, ribs and seeds removed, and finely chopped (1 cup)", 1, "", "Produce"), I("garlic, finely chopped", 3, "cloves", "Produce"), I("ground cumin", 1, "tsp", "Herbs & Spices"), I("dried oregano", 0.5, "tsp", "Pantry"), I("canned chipotle chile in adobo, finely chopped", 1, "", "Produce"), I("adobo sauce (from canned chile)", 2, "tbsp", "Pantry"), I("lacinato kale, tough stems removed, and roughly chopped", 1, "bunch", "Produce"), I("(14-oz.; 400g) cans pinto beans, rinsed and drained", 2, "", "Pantry"), I("(14-oz.; 400g) can diced tomatoes, with juice", 1, "", "Pantry"), I("vegetable stock", 1, "cups", "Pantry"), I("chopped pimiento-stuffed green olives", 0.25, "cups", "Pantry"), I("water", 5.5, "cups", "Pantry"), I("kosher salt", 2.5, "tsp", "Herbs & Spices"), I("coarse yellow cornmeal", 0.75, "cups", "Pantry"), I("masa harina", 0.5, "cups", "Pantry"), I("fresh or frozen corn kernels", 1.5, "cups", "Produce"), I("shredded plant-based cheddar-style cheese", 1, "cups", "Dairy & Eggs")], ["Heat the oven to 375°F (190°C) and give a 9x13-inch (23x33cm) baking dish a light coat of oil.", "Warm 3 tablespoons of the extra-virgin olive oil in a large sauté pan on medium-high. Cook the yellow onion, green bell pepper, and garlic for 3 minutes, adjusting the heat so they do not burn.", "Add the cumin, oregano, chipotle chile, adobo sauce, and kale and cook 5 minutes, stirring often.", "Add the pinto beans, tomatoes and their juice, vegetable stock, and green olives. Cook 10 minutes until everything is tender and the sauce has thickened a little.", "Meanwhile, bring the water to a boil in a large saucepan on high. Add the kosher salt, then slowly whisk in the cornmeal and masa harina. Lower the heat to medium and cook 15 minutes, stirring often.", "Stir the corn and the last tablespoon of olive oil into the cornmeal.", "Spread half the cornmeal mixture over the bottom of the baking dish, add the vegetable mixture, and cover with the rest of the cornmeal. Sprinkle with the cheese and bake 40 minutes. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-065", "Cassoulet", "American", ["section-book-plant-based"], "veg", "green", 45, "This slow-cooked comfort-food dish is perfect to pop in the oven on a snowy day.", [I("dried white beans, such as flageolet or great northern", 2, "cups", "Pantry"), I("vegetable stock, preferably homemade", 4, "cups", "Pantry"), I("extra-virgin olive oil", 0.5, "cups", "Pantry"), I("medium leeks, white and light green parts, cut into ⅛-in. (3mm) pieces (2 cups)", 2, "", "Produce"), I("medium stalks celery, cut into ⅛-in. (3mm) pieces (1 cup)", 3, "", "Produce"), I("medium carrot, halved and cut into ⅛-in. (3mm) slices (1 cup)", 1, "", "Produce"), I("medium shallots, minced (½ cup)", 2, "", "Produce"), I("garlic, thinly sliced", 2, "cloves", "Produce"), I("fresh thyme leaves", 1, "tbsp", "Herbs & Spices"), I("herbes de Provence", 1, "tsp", "Herbs & Spices"), I("tomato paste", 2, "tbsp", "Pantry"), I("dry red wine", 1.5, "cups", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("finely chopped fresh Italian flat-leaf parsley", 0.5, "cups", "Produce")], ["Heat the oven to 300°F (150°C).", "Rinse and sort the white beans, drain, and put them in a heavy lidded Dutch oven (earthenware, cast iron, or stainless steel) with the vegetable stock. Set aside.", "Warm the extra-virgin olive oil in a medium sauté pan on medium-high. Add the leeks, celery, carrot, and shallots and stir for 5 minutes.", "Stir in the herbes de Provence, thyme, and garlic for 1 minute.", "Mix in the tomato paste, then the red wine, kosher salt, and black pepper. Stir well and take off the heat.", "Pour the vegetables over the beans, stir gently, cover, and bake for 3½ hours, stirring once or twice, until the beans are tender. Take the lid off for the final hour.", "Stir in the parsley and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-066", "Crispy Quinoa Cakes", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Quinoa and lentils form a crispy exterior and tender interior in these savory little bites.", [I("flax meal (ground flaxseeds)", 2, "tbsp", "Pantry"), I("warm water", 6, "tbsp", "Pantry"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("medium red onion, finely chopped (¼ cup)", 0.25, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("lacinato kale, stemmed and finely chopped", 1, "bunch", "Produce"), I("cooked quinoa", 2, "cups", "Pantry"), I("cooked brown or green lentils", 1.5, "cups", "Pantry"), I("roasted pumpkin seeds, roughly chopped", 0.25, "cups", "Pantry"), I("finely chopped fresh Italian flat-leaf parsley", 0.25, "cups", "Produce"), I("finely chopped fresh cilantro", 2, "tbsp", "Produce"), I("tahini", 2, "tbsp", "Pantry"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce"), I("all-purpose flour", 2, "tbsp", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("ground cumin", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Heat the oven to 400°F (200°C) and line a baking sheet with parchment.", "Whisk the flax meal with the warm water in a small bowl and set aside.", "Warm 2 tablespoons of the extra-virgin olive oil in a medium sauté pan on medium-high. When it shimmers, cook the red onion about 3 minutes, stirring often, until translucent and just golden at the edges.", "Add the garlic, lower the heat to medium, and stir 30 seconds. Add the kale and cook about 5 minutes, stirring now and then. Take off the heat and let cool slightly.", "Combine the quinoa, lentils, pumpkin seeds, parsley, and cilantro in a large bowl.", "Add the tahini, all-purpose flour, and lemon juice to the flax mixture and whisk until smooth and add it to the quinoa. Add the kosher salt, cumin, black pepper, and the kale and mix thoroughly.", "With wet hands, shape the mixture into 12 balls and press each into a 1-inch (2.5cm) thick cake on the baking sheet. Brush lightly with the remaining olive oil and bake 20 minutes until golden and crisp. Serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-067", "Quinoa Vegetable Salad", "American", ["section-book-plant-based"], "veg", "green", 45, "Nutty quinoa teams up with edamame, kale, and crunchy jicama for a protein-packed powerhouse of a salad that's perfect for lunches, picnics, and potluck suppers.", [I("quinoa", 1, "cups", "Pantry"), I("water", 1.5, "cups", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("curly kale, leaves only", 1, "bunch", "Produce"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("garlic, finely chopped", 1, "cloves", "Produce"), I("apple cider vinegar", 2, "tbsp", "Pantry"), I("tahini", 2, "tbsp", "Pantry"), I("small jicama, cut in ¼-in. (.5cm) dice (about 2 cups)", 1, "", "Produce"), I("frozen, fully cooked edamame, thawed", 1, "cups", "Produce"), I("small red onion, very thinly sliced", 0.5, "", "Produce"), I("toasted sliced almonds", 0.5, "cups", "Pantry"), I("dried cranberries", 0.5, "cups", "Pantry")], ["Toast the quinoa in a dry medium saucepan with a tight lid on medium-high for 1 minute, stirring constantly.", "Add the water and ½ teaspoon of the kosher salt, bring to a boil, then cover and cook on low for 15 minutes. Leave covered off the heat for 10 minutes, then fluff with a fork.", "In a large bowl, toss the kale with a pinch of the kosher salt plus 1 tablespoon each of the lemon juice and extra-virgin olive oil. Massage with your hands for 5 minutes until soft and wilted, then mix in the garlic.", "Whisk the rest of the lemon juice, the remaining 2 tablespoons oil, the remaining kosher salt, the apple cider vinegar, and the tahini in a small bowl.", "Add the quinoa and edamame, the jicama and red onion, the almonds and cranberries, and the dressing to the kale and toss. Serve warm or cold."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-068", "Arancini (Risotto Balls)", "American", ["section-book-plant-based"], "veg", "soup", 45, "These crunchy-on-the-outside, creamy-on-the-inside rice balls are the perfect choice to serve at a party when you want to indulge yourself and your guests.", [I("all-purpose flour", 1, "cups", "Pantry"), I("water", 0.5, "cups", "Pantry"), I("panko breadcrumbs", 1.5, "cups", "Pantry"), I("batch Risotto Milanese, or 5 cups your favorite risotto, chilled overnight", 0.5, "", "Pantry"), I("(½-in.; 1.25cm) cubes plant-based mozzarella cheese", 10, "", "Dairy & Eggs"), I("frozen peas", 0.25, "cups", "Produce"), IN("Grapeseed oil", 1, "", "Pantry"), IN("Tomato Sauce", 1, "", "Pantry")], ["Line two baking sheets with parchment.", "Set out the all-purpose flour, water, and panko in three small, shallow bowls.", "Take ½-cup portions of the cold Risotto Milanese and, with wet hands, roll each into a ball around 1 cube of mozzarella cheese and a few peas. Set them on one baking sheet.", "One at a time, roll each ball through the flour, dunk it in the water, and coat it thoroughly in panko. Roll in flour once more, shake off the excess, and place on the second sheet. Chill 30 minutes or overnight.", "Shortly before serving, heat the oven to 250°F (120°C).", "Pour 3 or 4 inches of grapeseed oil (7.5 to 10cm deep) into a wide saucepan and bring it on medium-high to 375°F (190°C) on a deep-fry thermometer. Fry 3 or 4 balls at a time about 3 minutes, turning often, until golden all over. Drain on a rack set over a baking pan and hold in the warm oven as you fry the rest. Serve hot with Tomato Sauce for dipping."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-069", "Farro Risotto with Roasted Fennel and Mushrooms", "American", ["section-book-plant-based"], "veg", "roast", 45, "with Roasted Fennel and Mushrooms (T) Farro is an ancient grain.", [I("farro", 2, "cups", "Pantry"), I("kosher salt", 1.5, "tsp", "Herbs & Spices"), I("(10-oz.; 285g) pkg. small cremini (baby bella) mushrooms, quartered", 1, "", "Produce"), I("medium bulbs fennel, tops removed, cut into ½-in. (1.25cm) chunks", 2, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("vegetable stock", 2, "cups", "Pantry"), I("scallions, white and light green parts separated from dark green parts, thinly sliced", 1, "bunch", "Produce"), I("dry white wine", 0.5, "cups", "Pantry")], ["Heat the oven to 400°F (200°C) and line a rimmed baking sheet with parchment.", "Put the farro and 1 teaspoon of the kosher salt in a medium saucepan with water to come 1 inch (2.5cm) above it. Let it boil on high, then cook at a brisk simmer on medium for 20 minutes, stirring now and then. Drain and set aside.", "Toss the fennel, garlic, and cremini mushrooms with 2 tablespoons of the extra-virgin olive oil on the baking sheet and roast 20 minutes, stirring once or twice.", "Bring the vegetable stock to a simmer in a small saucepan on medium-high.", "Warm the remaining 2 tablespoons oil in a large sauté pan on medium-high and stir the white and light green scallion slices for 1 minute.", "Add the farro and white wine and stir until the wine has cooked away. Add 1 cup of the hot stock and stir until absorbed.", "Add the rest of the stock with the roasted vegetables and stir until absorbed.", "Mix in the dark green scallion slices, season with the remaining ½ teaspoon kosher salt, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-070", "Whole-Wheat Pasta e Ceci", "American", ["section-book-plant-based"], "veg", "bowl", 45, "(Pasta with Chickpeas) (1) (3) In this easy dish, whole-wheat pasta and chickpeas combine in a spicy tomato sauce thats just brothy enough to eat with a spoon.", [I("(225g) tube-shape whole-wheat pasta, such as chocchiole, or medium shells", 8, "oz", "Pantry"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("large sweet onion, minced (¾ cup)", 0.5, "", "Produce"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("garlic, minced", 2, "cloves", "Produce"), I("crushed red pepper flakes", 0.25, "tsp", "Herbs & Spices"), I("tomato paste", 1, "tbsp", "Pantry"), I("(28-oz.; 800g) can peeled Italian plum tomatoes, with juice, lightly crushed by hand", 1, "", "Pantry"), I("filtered water or vegetable stock", 0.5, "cups", "Pantry"), I("(14.5-oz.; 410g) can chickpeas, rinsed and drained", 1, "", "Pantry"), I("dry white wine", 0.25, "cups", "Pantry"), I("dried oregano", 0.25, "tsp", "Pantry")], ["Boil the whole-wheat pasta in a large pot of salted water on medium-high until al dente, following the package. Drain without rinsing and set aside.", "Meanwhile, warm the extra-virgin olive oil in a large saucepan on medium-high and cook the sweet onion with the kosher salt about 5 minutes, stirring often, until soft and translucent.", "Add the garlic and red pepper flakes and stir 30 seconds. Mix in the tomato paste, then add the plum tomatoes with their juice and the filtered water. Bring to a boil, lower to medium, and cook 5 minutes.", "Add the chickpeas and pasta and cook 2 minutes.", "Stir in the white wine and oregano, take off the heat, and serve at once."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-071", "Swiss Chard Ravioli", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Swiss chard and almonds make a creamy and delicious ravioli filling.", [I("raw almonds", 0.5, "cups", "Pantry"), I("extra-virgin olive oil", 3, "tbsp", "Pantry"), I("garlic, finely chopped", 4, "cloves", "Produce"), I("bunches Swiss chard, leaves only, roughly chopped", 2, "", "Produce"), I("water", 1, "tbsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), IN("Juice of ½ lemon (1 TB.)", 1, "", "Produce"), I("nutritional yeast", 1, "tbsp", "Pantry"), I("water", 1, "tsp", "Pantry"), I("wonton wrappers, or 1 batch Fresh Pasta Dough", 40, "", "Pantry")], ["Cover the almonds with cold water and soak at least 4 hours or overnight. Pour off the soaking water, rinse, and drain.", "Warm the extra-virgin olive oil in a large sauté pan on medium-high and stir the garlic 30 seconds. Add the Swiss chard still damp from washing and cook about 10 minutes, stirring often, until tender. Add the tablespoon of water if the pan dries out. Season with the kosher salt and black pepper and let cool a little.", "Pulse the almonds, chard, lemon juice, and nutritional yeast in a food processor until smooth, adding the teaspoon of water if needed to bring it together. Let cool completely.", "Working in small batches, lay wonton wrappers on a lightly floured surface. Put about 1½ teaspoons filling in the middle of each, wet the edges with water, and pinch shut, pushing out the air. (If using Fresh Pasta Dough, roll it about ⅛ inch [3mm] thick, cut 3-inch [7.5cm] rounds, and fill the same way.)", "Set a large pot of salted water on medium-high and let it boil. Slip in the ravioli and cook 3 to 5 minutes until tender. Serve with the sauce of your choice."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-072", "One-Pan Pasta Primavera", "American", ["section-book-plant-based"], "veg", "bowl", 45, "This is a \"throw everything in one pan' pasta recipe.", [I("extra-virgin olive oil", 0.25, "cups", "Pantry"), I("medium yellow onion, halved and thinly sliced", 1, "", "Produce"), I("garlic, thinly sliced", 2, "cloves", "Produce"), I("(340g) thin spaghetti", 12, "oz", "Pantry"), I("vegetable stock or water", 4.5, "cups", "Pantry"), I("(14-oz.; 400g) can diced tomatoes, with juice", 1, "", "Pantry"), I("fresh or frozen broccoli florets", 2, "cups", "Produce"), I("medium carrot, peeled, halved, and thinly sliced (½ cup)", 1, "", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("(5-oz.; 140g) pkg. baby spinach", 1, "", "Produce"), I("fresh or frozen baby peas", 0.5, "cups", "Produce"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices")], ["Warm the extra-virgin olive oil on medium-high in an extra-large lidded sauté pan and cook the yellow onion 2 minutes.", "Add the garlic, spaghetti, vegetable stock, tomatoes and juice, carrot and broccoli, and the kosher salt. Let it come to a boil, cover, lower to medium-low, and cook 3 minutes.", "Uncover and keep cooking at a lively simmer about 8 minutes, stirring constantly, until the pasta is tender and the liquid is absorbed.", "Add the peas, spinach, and black pepper, toss 1 minute, and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-073", "Sesame Tofu Cutlets", "American", ["section-book-plant-based"], "veg", "green", 45, "Tofu cutlets are marinated in ginger, soy, sesame, and garlic and fried crisp with a sesame and breadcrumb crust. They are great with steamed greens and rice, on a salad, or in a sandwich.", [I("(16-oz.; 450g) pkg. firm tofu", 1, "", "Dairy & Eggs"), I("reduced-sodium tamari", 2, "tbsp", "Pantry"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce"), I("toasted sesame oil", 1, "tbsp", "Pantry"), I("grated fresh ginger", 1, "tbsp", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("panko breadcrumbs", 0.5, "cups", "Pantry"), I("sesame seeds", 0.25, "cups", "Pantry"), I("grapeseed oil", 0.25, "cups", "Pantry")], ["Cut the tofu through its thickness into 3 slabs, then halve each slab. Press between thick layers of paper towels under a heavy weighted plate for 30 minutes.", "Whisk the ginger and garlic with the tamari, sesame oil, and lemon juice in a large baking dish. Add the tofu and refrigerate 2 hours, turning once or twice.", "Mix the panko and sesame seeds in a small bowl.", "Coat each piece of tofu in the crumbs, dip it back in the marinade, and coat again.", "Heat the grapeseed oil in a large frying pan on medium-high until shimmering. Fry the cutlets about 3 minutes per side, turning once and adjusting the heat so they do not burn, until crisp and golden."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-074", "Hearty Seitan Roast", "American", ["section-book-plant-based"], "veg", "dessert", 45, "A simple seitan loaf is browned and then baked in a savory, sweet, and sour sauce with aromatic vegetables for the perfect holiday meal centerpiece dish.", [I("olive oil", 2, "tbsp", "Pantry"), I("batch Basic Seitan", 0.5, "", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("large yellow onion, cut in ½-in. (1.25cm) wedges", 1, "", "Produce"), I("medium carrots, peeled and cut into 1-in. (2.5cm) chunks", 2, "", "Produce"), I("medium parsnips, peeled and cut into 1-in. (2.5cm) chunks", 2, "", "Produce"), I("garlic, thinly sliced", 2, "cloves", "Produce"), I("herbes de Provence", 1, "tsp", "Herbs & Spices"), I("vegetable stock (preferably Basic Seitan cooking stock)", 1, "cups", "Pantry"), I("dry red wine", 0.5, "cups", "Pantry"), I("ketchup", 2, "tbsp", "Pantry"), I("reduced-sodium tamari", 1, "tbsp", "Pantry"), I("balsamic vinegar", 1, "tbsp", "Pantry")], ["Heat the oven to 375°F (190°C).", "Warm 1 tablespoon of the olive oil in a large skillet, cast iron if you have it, on medium-high.", "Season the Basic Seitan all over with ½ teaspoon of the kosher salt and ¼ teaspoon of the black pepper. Brown it in the skillet, turning every minute or two, until colored on all sides.", "In a small roasting pan, toss the yellow onion, carrots, parsnips, and garlic with the remaining olive oil, the herbes de Provence, and the rest of the salt and pepper. Set the browned seitan on top.", "Whisk the ketchup, tamari, and balsamic vinegar with the vegetable stock and red wine in a small saucepan on high. Cook about 10 minutes, stirring often, until slightly thickened and reduced to 1 cup. Pour over the seitan and vegetables.", "Cover with foil and bake 20 minutes, then uncover and bake 10 minutes more.", "Slice the seitan as thinly as you can with a sharp serrated knife, arrange on a platter, and spoon the vegetables and sauce over. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-075", "Tempeh Milanese", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Tempeh is breaded, quickly fried, and served with a lemon arugula salad for a meatless take on the classic Italian chicken Milanese.", [I("(8-oz.; 225g) pkg. tempeh", 1, "", "Pantry"), I("water", 0.5, "cups", "Pantry"), IN("Juice of 2 lemons (4 TB.)", 1, "", "Produce"), I("reduced-sodium tamari", 2, "tbsp", "Pantry"), I("extra-virgin olive oil", 4, "tbsp", "Pantry"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("Italian-seasoned panko breadcrumbs", 1, "cups", "Pantry"), I("grapeseed oil", 0.5, "cups", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.25, "tsp", "Herbs & Spices"), I("baby arugula", 4, "cups", "Produce"), I("grape tomatoes, halved", 2, "cups", "Produce"), I("medium red onion, very thinly sliced", 0.5, "", "Produce"), I("pitted kalamata olives", 0.25, "cups", "Pantry")], ["Heat the oven to 350°F (180°C).", "Split the tempeh horizontally and cut each half into 4 equal cutlets. Lay them in a single layer in a baking dish.", "Whisk the water, 2 tablespoons of the lemon juice, the tamari, 2 tablespoons of the extra-virgin olive oil, and the garlic in a small bowl. Pour over the tempeh, seal the dish with foil, and bake 50 minutes. Uncover, drain, and let cool slightly.", "Put the Italian-seasoned panko in a shallow bowl.", "Heat the grapeseed oil in a large frying pan on medium-high until it shimmers.", "Coat the cutlets in panko and fry about 2 minutes per side, turning once, until crisp and golden. Lower the heat if they brown too fast.", "Toss the arugula in a large bowl with the remaining 2 tablespoons each lemon juice and olive oil, plus the kosher salt and black pepper. Divide among 4 plates, add the grape tomatoes, red onion, and kalamata olives, and top each with 2 cutlets. Serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-076", "Seitan and Dumplings", "American", ["section-book-plant-based"], "veg", "bowl", 45, "Simple, delicious, cornmeal and herh-spiked hatter puffs up into pillowy dumplings that are nestled atop a stew of seitan chunks and tender vegies.", [I("grapeseed oil", 2, "tbsp", "Pantry"), I("loaf Basic Seitan, pulled into small chunks before simmering, or 1 (1-lb.; 450g) pkg. seitan pieces", 1, "", "Pantry"), I("large yellow onion, halved and thinly sliced", 1, "", "Produce"), I("large carrots, peeled and cut into ½-in. (1.25cm) rounds", 2, "", "Produce"), I("(8-oz.; 225g) pkg. button mushrooms, quartered", 1, "", "Produce"), I("large stalks celery, cut in ½-in. (1.25cm) slices (1 cup)", 2, "", "Produce"), I("kosher salt", 2, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 1, "tsp", "Herbs & Spices"), I("soy or hemp milk", 1.5, "cups", "Dairy & Eggs"), I("apple cider vinegar", 1, "tsp", "Pantry"), IN("3 TB. plus 1½ cups all-purpose flour", 1, "", "Pantry"), I("coarse yellow cornmeal", 0.5, "cups", "Pantry"), I("baking powder", 2, "tbsp", "Pantry"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("dried thyme", 0.5, "tsp", "Pantry"), I("Bell's seasoning or poultry seasoning", 0.5, "tsp", "Herbs & Spices"), I("vegetable stock", 5, "cups", "Pantry"), I("fresh or frozen tiny green peas", 1, "cups", "Produce")], ["Warm 1 tablespoon of the grapeseed oil in a Dutch oven on medium-high.", "Brown the Basic Seitan in batches for 5 minutes, stirring gently. Move each batch to a plate and keep covered.", "Add the rest of the oil to the pot with the yellow onion and carrots, the celery and button mushrooms, 1 teaspoon of the kosher salt, and ½ teaspoon of the black pepper. Cook 5 minutes, stirring often and turning down the heat if needed.", "Whisk the soy milk and apple cider vinegar in a medium bowl and leave to curdle a little.", "In a large bowl, whisk 1½ cups of the all-purpose flour with the cornmeal, baking powder, parsley, thyme, Bell's seasoning, and the remaining salt and pepper. Pour in the milk mixture and stir only until combined, without kneading. Rest 10 minutes.", "Sprinkle the remaining 3 tablespoons flour over the vegetables and stir 1 minute. Pour in the vegetable stock, scraping up the browned bits.", "Add the seitan and peas and bring to a boil. Drop heaping tablespoons of batter over the surface, spaced evenly, for about 10 dumplings. Cover, turn the heat to low, and cook 15 minutes without lifting the lid. Uncover, take off the heat, and serve."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-077", "Seitan Satay", "American", ["section-book-plant-based"], "veg", "green", 45, "Skewers of marinated tempeh are grilled or broiled and dipped in tasty peanut-tamarind dressing.", [I("loaf Basic Seitan, cut into 1-in. (2.5cm) chunks", 1, "", "Pantry"), IN("¼ cup plus 2 TB. reduced-sodium tamari", 1, "", "Pantry"), I("water", 0.25, "cups", "Pantry"), I("toasted sesame oil", 1, "tbsp", "Pantry"), I("melted coconut oil", 1, "tbsp", "Pantry"), I("grated fresh ginger", 3, "tbsp", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("tamarind paste", 2, "tbsp", "Pantry"), I("hot (not boiling) water", 2, "tbsp", "Pantry"), I("chunky peanut butter", 0.5, "cups", "Pantry"), I("full-fat coconut milk, well shaken", 0.5, "cups", "Dairy & Eggs"), I("crushed red pepper flakes", 1, "tsp", "Herbs & Spices")], ["Lay the Basic Seitan in a single layer in a baking dish.", "Whisk ¼ cup of the tamari with the water, sesame oil, coconut oil, 1 tablespoon of the ginger, and the garlic in a small bowl. Pour over the seitan, stir, cover, and refrigerate 2 hours or overnight.", "Leave 8 bamboo skewers soaking in warm water for a minimum of 30 minutes, then drain.", "Heat a broiler, grill, or grill pan for high, direct heat and lightly oil the pan or grates.", "In a medium bowl, whisk the tamarind paste with the hot water until soft. Whisk in the peanut butter, coconut milk, the rest of the ginger and tamari, and the red pepper flakes.", "Thread the seitan onto the skewers and cook 5 to 7 minutes, turning once or twice, until browned all over. Serve hot with the peanut sauce."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-078", "Maple-Glazed Tofu", "American", ["section-book-plant-based"], "veg", "roast", 45, "Enjoy this sweet and savory grilled tofu with a side of Southern-Style Braised Greens and a side of brown rice, or make a sensational sandwich with crisp lettuce, fresh tomato, and a smear of spicy mustard.", [I("(450g) firm or extra-firm tofu, sliced into 8 slices", 1, "lb", "Dairy & Eggs"), I("balsamic vinegar", 0.25, "cups", "Pantry"), I("maple syrup", 3, "tbsp", "Pantry"), I("extra-virgin olive oil", 2, "tbsp", "Pantry"), I("reduced-sodium tamari", 1, "tbsp", "Pantry")], ["Press the tofu between thick layers of paper towels under a heavy weighted plate for 15 minutes.", "Meanwhile, bring the balsamic vinegar, maple syrup, 1 tablespoon of the extra-virgin olive oil, and the tamari to a boil in a small saucepan on medium-high. Cook about 10 minutes, stirring often, until reduced to a sticky glaze.", "Heat a grill or grill pan to high and brush with the remaining tablespoon of oil.", "Blot the tofu dry, brush with glaze, and grill roughly 2 minutes a side, flipping gently and basting with more glaze. Serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-079", "Tempeh Bacon", "American", ["section-book-plant-based"], "veg", "skillet", 45, "This tempeh bacon is crispy, salty, smoky, and a little sweet.", [I("(8-oz.; 225g) pkg. tempeh", 1, "", "Pantry"), I("water", 0.25, "cups", "Pantry"), I("reduced-sodium tamari", 3, "tbsp", "Pantry"), I("maple syrup", 2, "tbsp", "Pantry"), I("apple cider vinegar", 1, "tbsp", "Pantry"), I("brown sugar", 1, "tbsp", "Pantry"), I("smoked sea salt", 2, "tsp", "Herbs & Spices"), I("toasted sesame oil", 1, "tsp", "Pantry"), I("smoked paprika", 0.5, "tsp", "Herbs & Spices"), I("coarsely ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("grapeseed oil", 1, "tbsp", "Pantry")], ["With a serrated knife, cut the tempeh lengthwise into thin strips, at least 12 per package. Arrange them, not overlapping, in a large baking pan.", "Whisk the water and tamari with the maple syrup and brown sugar, the apple cider vinegar, the sesame oil, and the smoked sea salt, smoked paprika, and black pepper in a small saucepan on high. Bring to a boil, take off the heat, and pour over the tempeh. Cover and refrigerate for 3 hours at minimum and as long as 3 days.", "Warm the grapeseed oil in a large heavy frying pan, ideally cast iron, on medium. Let the strips drip briefly without drying them and discard the leftover marinade. Fry a few at a time, turning every 2 minutes and watching closely, until browned and crisp on both sides. Serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-080", "Seitan Gyros", "American", ["section-book-plant-based"], "veg", "roast", 45, "Sliced seitan is marinated with traditional Greek flavors of lemon, extra-virgin olive oil, and garlic; grilled until nicely charred; and served on warm pita with all the fixings.", [I("extra-virgin olive oil, plus more for grilling", 0.25, "cups", "Pantry"), IN("Juice of 2 lemons (¼ cup)", 1, "", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 2, "tbsp", "Produce"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("garlic, crushed and finely chopped", 1, "cloves", "Produce"), I("loaf Basic Seitan", 1, "", "Pantry"), I("pita breads, preferably pocketless", 6, "", "Bakery"), I("shredded romaine lettuce", 3, "cups", "Produce"), I("plum tomatoes, cored and cut into small dice", 3, "", "Produce"), I("small red onion, very thinly sliced", 0.5, "", "Produce"), I("batch Tzatziki, or 1 cup plain, plant-based yogurt mixed with juice of ½ lemon (1 TB.)", 1, "", "Dairy & Eggs"), I("sweet paprika", 1, "tsp", "Herbs & Spices")], ["Whisk the extra-virgin olive oil, lemon juice, parsley, kosher salt, black pepper, and garlic in a small bowl.", "Slice the Basic Seitan paper-thin and spread the slices in one layer in a large baking dish. Pour the marinade over and leave at room temp for 25 minutes.", "Heat a grill or grill pan for high, direct heat and brush with a little olive oil.", "Lift the seitan from the marinade and grill about 1 minute per side until charred.", "Warm the pita breads briefly on the grill. Share the seitan among them and add the romaine lettuce, plum tomatoes, and red onion. Spoon over the Tzatziki, dust with the sweet paprika, roll up, and serve right away."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-081", "Easy Slow-Rise Oatmeal Bread", "American", ["section-book-plant-based"], "veg", "bowl", 45, "This bread is simple, foolproof, easy to double, and just plain good.", [I("rolled oats", 0.75, "cups", "Pantry"), IN("3 cups plus 2 or 3 TB. all-purpose flour", 1, "", "Pantry"), I("kosher salt", 1, "tsp", "Herbs & Spices"), I("granulated cane sugar", 0.5, "tsp", "Pantry"), I("active dry yeast", 0.5, "tsp", "Pantry"), I("very warm (110°F; 43°C) water", 1.5, "cups", "Pantry"), I("nondairy milk", 1, "tsp", "Dairy & Eggs")], ["Grind the rolled oats to a coarse flour in a food processor or blender.", "In a large bowl, mix the ground oats, 3 cups of the all-purpose flour, the kosher salt, sugar, and yeast. Gradually stir in the warm water until a rough, shaggy dough forms. Dust with 1 or 2 tablespoons more flour and knead 50 turns; it will be sticky but hold together. Return to the bowl, cover with lightly greased plastic wrap, and let rise at room temp for 6 to 8 hours.", "Grease a 9-inch (23cm) loaf pan.", "Punch the dough down and knead 1 or 2 minutes with a little more flour. Shape it roughly into a loaf and set it in the pan. Cover and let rise at room temperature about 5 hours more, until doubled.", "About 20 minutes before baking, heat the oven to 400°F (200°C).", "Slash the top of the loaf with a sharp knife, brush with the nondairy milk, and bake 45 minutes, until golden and hollow-sounding when tapped underneath. Let cool completely in the pan on a rack before slicing."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-082", "Herbed Mushroom and Leek Tart", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Puff pastry is topped with tender, sweet leeks and sautéed mushrooms in this beautiful free-form rectangular tart.", [I("extra-virgin olive oil", 8, "tbsp", "Pantry"), I("leeks, sliced (3 cups)", 1, "bunch", "Produce"), I("nutritional yeast", 1, "tbsp", "Pantry"), I("(6-oz.; 170g) pkg. cremini (baby bella) mushrooms, thinly sliced", 1, "", "Produce"), I("(6-oz.; 170g) pkg. shiitake mushrooms, stemmed and thinly sliced", 1, "", "Produce"), I("garlic, finely chopped", 2, "cloves", "Produce"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("freshly ground black pepper", 0.5, "tsp", "Herbs & Spices"), I("chopped fresh thyme", 1, "tbsp", "Herbs & Spices"), I("minced fresh chives", 1, "tbsp", "Produce"), I("finely chopped fresh Italian flat-leaf parsley", 1, "tbsp", "Produce"), I("sheet puff pastry", 1, "", "Frozen")], ["Heat the oven to 400°F (200°C) and line a baking sheet with parchment.", "Warm 2 tablespoons of the extra-virgin olive oil in a large sauté pan on medium and cook the leeks 10 minutes, stirring 2 or 3 times.", "Mix the nutritional yeast into the leeks, spoon into a small bowl, and set aside.", "Wipe out the pan and set it on medium-high with 4 tablespoons more oil. When hot, cook the cremini and shiitake mushrooms with the garlic for 10 minutes, stirring often and adding the last 2 tablespoons oil if they stick.", "Stir in the kosher salt, black pepper, thyme, chives, and parsley. Take off the heat and let cool a little.", "On a floured surface, roll the puff pastry into a rectangle of 14x10 inches (35.5x25cm), cut it in half crosswise, and set both pieces on the baking sheet. Fold the outer ½ inch (1.25cm) in to make a rim, press it firmly, and prick the center all over with a fork.", "Spread the leeks over the pastry and top with the mushrooms. Bake 20 minutes until puffed and golden. Slice and serve hot."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-083", "Pumpkin Pudding Pie", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Creamy pumpkin pudding, spiced with a hit of cinnamon and ginger, fills a sweet and salty gingersnap crust for a perfectly homey pudding pie.", [I("(285g) gingersnap cookies (about 3 cups broken cookies)", 10, "oz", "Produce"), I("melted plant-based butter or coconut oil", 4, "tbsp", "Pantry"), I("kosher salt", 2, "tsp", "Herbs & Spices"), I("instant tapioca, such as Minute Tapioca", 0.25, "cups", "Pantry"), I("ground cinnamon", 1, "tsp", "Herbs & Spices"), I("ground ginger", 0.5, "tsp", "Herbs & Spices"), I("brown sugar, lightly packed", 0.75, "cups", "Pantry"), I("coconut milk coffee creamer", 1, "cups", "Dairy & Eggs"), I("nondairy milk", 1, "cups", "Dairy & Eggs"), I("maple syrup", 1, "tbsp", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), I("cornstarch", 0.25, "cups", "Pantry"), I("(15-oz.; 420g) can pumpkin purée, or 2 cups fresh pumpkin purée", 1, "", "Pantry")], ["Heat the oven to 350°F (180°C).", "Process the gingersnap cookies, butter, and 1 teaspoon of the kosher salt in a food processor to coarse crumbs. Press the crumbs into a deep-dish 10-inch (25cm) pie pan, set it on a rimmed baking sheet, and bake 20 minutes. Let cool.", "Meanwhile, whisk the tapioca, cinnamon, ginger, brown sugar, and remaining salt together in a medium saucepan. Set on low and gradually whisk in the coffee creamer, ½ cup of the nondairy milk, the maple syrup, and the vanilla extract. Raise to medium and bring to a boil.", "Whisk the cornstarch with the remaining ½ cup milk in a small bowl, then whisk it into the pan. Keep whisking gently about 3 minutes until thick.", "Whisk in the pumpkin purée, take off the heat, and let cool 10 minutes.", "Spread the filling in the crust and smooth the top. Let cool 10 minutes, cover, and refrigerate overnight. Leftovers keep up to 2 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-084", "Apple Crumble Pie", "American", ["section-book-plant-based"], "veg", "dessert", 45, "The nutty streusel crumble on this pie crowns a filling of tender, sweet, cinnamon-kissed apples.", [I("whole-wheat pastry flour", 1, "cups", "Pantry"), I("walnuts", 1, "cups", "Pantry"), I("brown sugar, lightly packed", 0.5, "cups", "Pantry"), I("ground cinnamon", 2.5, "tsp", "Herbs & Spices"), I("chilled plant-based butter, cut in small cubes", 4, "tbsp", "Dairy & Eggs"), I("batch Pie Pastry, or prepared crust for a single-crust deep-dish pie", 0.5, "", "Pantry"), I("granulated sugar", 0.75, "cups", "Pantry"), I("instant tapioca, such as Minute Tapioca", 1, "tbsp", "Pantry"), I("medium apples, such as Granny Smith or Northern Spy, peeled, cored, and thinly sliced (about 2 lb.; 1kg)", 7, "", "Produce"), IN("Juice of 1 lemon (2 TB.)", 1, "", "Produce")], ["Heat the oven to 350°F (180°C).", "Pulse the pastry flour, walnuts, brown sugar, and ½ teaspoon of the cinnamon in a food processor. Add the butter and pulse to coarse crumbs. Set this topping aside.", "Roll the Pie Pastry to a 13-inch (33cm) round and ease it into a deep-dish 10-inch (25cm) pie plate. Turn the 1-inch (2.5cm) overhang under, pinch into a rim, and crimp. Chill while you make the filling.", "In a large bowl, whisk the remaining 2 teaspoons cinnamon with the granulated sugar and tapioca. Add the apples and lemon juice, toss well, and pile into the crust.", "Squeeze handfuls of topping into clumps and crumble them evenly over the apples until it is all used.", "Put the pie on a rimmed baking sheet and bake it in the lowest third of the oven for roughly 1 hour, until the top is golden and the filling bubbles. Check once or twice and lay foil over the top if it darkens too quickly.", "Let cool at room temp for 3 hours before slicing."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-085", "Blueberry Peach Cobbler", "American", ["section-book-plant-based"], "veg", "dessert", 45, "This delightful dish is a fabulous way to showcase summer's finest fruits.", [I("plant-based butter", 4, "tbsp", "Dairy & Eggs"), I("cornstarch", 2, "tbsp", "Pantry"), I("sugar", 1, "cups", "Pantry"), I("(450g) fresh peaches, unpeeled, pitted, and sliced", 1, "lb", "Produce"), I("fresh blueberries", 4, "cups", "Pantry"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices"), IN("Juice of ½ lemon (1 TB.)", 1, "", "Produce"), I("all-purpose flour", 1, "cups", "Pantry"), I("baking powder", 2, "tsp", "Pantry"), I("kosher salt", 0.25, "tsp", "Herbs & Spices"), I("coconut milk coffee creamer", 1, "cups", "Dairy & Eggs")], ["Heat the oven to 350°F (180°C).", "Melt the butter in the oven in a cast-iron skillet or casserole dish of 3 quarts (3L), leaving it in until melted.", "Whisk the cornstarch with ½ cup of the sugar in a large bowl. Add the peaches, blueberries, cinnamon, and lemon juice and toss gently.", "In a medium bowl, whisk the all-purpose flour with the rest of the sugar, the kosher salt, and the baking powder. Mix in the coffee creamer to make a rough dough.", "Take the hot pan out of the oven, spread the fruit over the bottom, and drop spoonfuls of the dough over the top. Bake on a baking sheet in the lowest third of the oven about 45 minutes. Serve warm."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-086", "Nutty Berry Streusel Bars", "American", ["section-book-plant-based"], "veg", "dessert", 45, "A gorgeous layer of jam peeks out from the coconut-laced streusel that tops these easy-to-make, deliciously crumbly bar cookies.", [I("almond flour", 1, "cups", "Pantry"), I("rolled oats", 1, "cups", "Pantry"), I("walnuts", 1, "cups", "Pantry"), I("all-purpose flour, or gluten-free flour blend", 0.5, "cups", "Pantry"), I("fine sea salt", 0.5, "tsp", "Herbs & Spices"), I("brown sugar, lightly packed", 0.5, "cups", "Pantry"), I("melted coconut oil", 0.5, "cups", "Pantry"), I("plant-based butter", 2, "tbsp", "Dairy & Eggs"), I("unsweetened dried coconut", 0.25, "cups", "Pantry"), I("blueberry, raspberry, or strawberry jam", 1, "cups", "Pantry")], ["Heat the oven to 375°F (190°C). Use parchment or foil to line a square 9-inch (23cm) baking pan, leaving a generous overhang, and grease lightly.", "Pulse the rolled oats and walnuts with the almond flour, all-purpose flour, and sea salt in a food processor to a coarse meal. Add the butter, brown sugar, and coconut oil and run the machine about 30 seconds. Set aside 1 cup of the mixture and press the rest firmly into the pan. Bake 10 minutes.", "Rub the coconut into the reserved mixture with your fingers.", "Spoon the jam over the baked base and spread it out.", "Scatter the coconut topping over the jam and bake 20 minutes more. Let cool completely before cutting into bars."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-087", "Cherry Cheesecake Squares", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Sometimes, plant-based food isn't just about being healthy—it's about dessert.", [I("chocolate sandwich cookies", 20, "", "Pantry"), I("plant-based butter, melted", 2, "tbsp", "Dairy & Eggs"), I("(8-oz.; 225g) pkg. soy cream cheese, softened", 2, "", "Dairy & Eggs"), I("(170g) vanilla soy yogurt", 6, "oz", "Dairy & Eggs"), IN("¼ cup plus 1 TB. confectioners’ sugar", 1, "", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), IN("Pinch sea salt", 1, "", "Herbs & Spices"), I("(21-oz.; 600g) can cherry pie filling", 1, "", "Pantry")], ["Heat the oven to 350°F (180°C). Use foil to line a square 9-inch (23cm) baking pan, letting several inches hang over each side, tuck the overhang under the pan edges, and grease the foil.", "Grind the chocolate sandwich cookies to fine crumbs in a food processor, then pulse in the butter. Press the crumbs firmly over the bottom of the pan with your hands or the base of a glass.", "Beat the soy cream cheese and vanilla soy yogurt in a large bowl with an electric mixer on medium-high until smooth.", "Beat in the confectioners' sugar, vanilla extract, and sea salt.", "Spread over the crust and bake 35 minutes, until set.", "Spoon the cherry pie filling over the warm cheesecake and let cool completely. Refrigerate at least 6 hours or overnight, then cut into 16 squares."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-088", "Triple Ginger Molasses Cookies", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Fill your cookie jar with these chewy, spicy, molasses and ginger treats, but be warned—they won't last long!", [I("raw turbinado sugar", 0.25, "cups", "Pantry"), I("ground cinnamon", 1, "tsp", "Herbs & Spices"), I("whole-wheat pastry flour", 2, "cups", "Pantry"), I("ground ginger", 2, "tbsp", "Herbs & Spices"), I("baking soda", 0.5, "tsp", "Pantry"), I("baking powder", 0.5, "tsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("sucanat", 1, "cups", "Pantry"), I("grapeseed oil", 0.5, "cups", "Pantry"), I("blackstrap molasses", 0.25, "cups", "Pantry"), I("nondairy milk, such as rice or coconut", 0.25, "cups", "Pantry"), I("grated fresh ginger", 1, "tbsp", "Produce"), I("candied ginger chips, or finely diced crystallized ginger", 0.25, "cups", "Pantry")], ["Heat the oven to 350°F (180°C) and line two baking sheets with parchment.", "Mix the turbinado sugar and cinnamon in a small bowl.", "In a medium bowl, whisk the pastry flour with the ground ginger, kosher salt, baking powder, and baking soda.", "In a second medium bowl, whisk the sucanat, grapeseed oil, molasses, nondairy milk, and fresh ginger until smooth.", "Stir the wet mixture into the dry, adding the candied ginger just before it is fully mixed. Chill the dough 15 minutes.", "Roll heaping tablespoons of dough into balls, coat in the cinnamon sugar, and set 2 inches (5cm) apart on the sheets. Bake 12 to 14 minutes until golden.", "Let cool 2 minutes on the sheets, then move to racks to cool completely. Keeps 5 days in an airtight container at room temperature."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-089", "Pineapple Cornmeal Upside-Down Cake", "American", ["section-book-plant-based"], "veg", "dessert", 45, "In this fun and fabulous retro classic, caramelized pineapple slices are topped with a tender cornmeal hatter and then flipped after haking.", [I("coconut milk coffee creamer or soy milk", 0.3333, "cups", "Dairy & Eggs"), I("apple cider vinegar", 1, "tsp", "Pantry"), I("all-purpose flour", 1, "cups", "Pantry"), I("fine yellow cornmeal", 0.25, "cups", "Pantry"), I("baking powder", 2, "tsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), IN("¼ cup plus 1 TB. grapeseed oil", 1, "", "Pantry"), I("small ripe banana, peeled and mashed", 1, "", "Produce"), I("granulated sugar", 0.5, "cups", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), I("pineapple juice (reserved from can or fresh pineapple)", 1, "tbsp", "Pantry"), I("brown sugar", 2, "tbsp", "Pantry"), I("(15-oz.; 420g) can organic pineapple rings in juice, cut in half, or 1 small fresh pineapple, peeled, cored, and cut into half-rings", 1, "", "Pantry")], ["Heat the oven to 350°F (180°C). Then grease a 9-inch (23cm) round springform pan or cake pan, wrapping the springform in foil.", "Whisk the coffee creamer with the apple cider vinegar in a small bowl and leave to curdle a little.", "In another small bowl, whisk the all-purpose flour, cornmeal, baking powder, and kosher salt.", "In a large bowl, whisk ¼ cup of the grapeseed oil with the banana, granulated sugar, and vanilla extract until smooth.", "Bring the remaining tablespoon of oil, the pineapple juice, and the brown sugar to a boil in a small saucepan on medium-high, stirring the whole time, and cook 1 minute. Pour this caramel into the pan and lay the pineapple half-rings over it in a neat pattern.", "Whisk the curdled creamer into the banana mixture, then fold in the flour mixture only until combined. Spread the batter over the pineapple and smooth with a spatula or a wet spoon.", "Bake 45 to 50 minutes, until a skewer in the center comes out clean and the top springs back.", "Run a knife around the edge and let cool completely. Release the sides, turn the cake out onto a platter, and lift off the pan base, loosening the pineapple with a thin knife if needed."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-090", "Fudgy Oatmeal Thumbprints", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Little cocoa and cinnamon-kissed oatmeal cookies get a fiber boost from walnuts and cacao nibs.", [I("flax meal (ground flaxseeds)", 2, "tbsp", "Pantry"), I("nondairy milk, such as almond", 0.5, "cups", "Dairy & Eggs"), I("rolled oats", 1, "cups", "Pantry"), I("all-purpose flour", 1, "cups", "Pantry"), I("unsweetened cocoa powder", 1, "tbsp", "Pantry"), I("baking powder", 2, "tsp", "Pantry"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("melted coconut oil", 0.5, "cups", "Pantry"), I("brown sugar, lightly packed", 0.5, "cups", "Pantry"), I("finely chopped walnuts", 0.5, "cups", "Pantry"), I("raw cacao nibs", 1, "tbsp", "Pantry"), I("finely chopped bittersweet chocolate or chocolate chips", 0.75, "cups", "Pantry"), I("plant-based coffee creamer", 0.25, "cups", "Dairy & Eggs"), I("maple syrup", 1, "tsp", "Pantry")], ["Heat the oven to 350°F (180°C) and line 2 rimmed baking sheets with parchment.", "Put the flax meal in a small bowl.", "Warm the nondairy milk in a small saucepan on medium until bubbles form at the edge. Pour over the flax, stir, and leave 10 minutes.", "Pulse the rolled oats in a food processor to a coarse meal. Tip into a large bowl and whisk in the all-purpose flour and cocoa powder with the cinnamon, kosher salt, and baking powder.", "Whisk the coconut oil, brown sugar, and flax mixture hard in a medium bowl until smooth. Stir into the dry mixture with a spatula or wooden spoon, and when nearly combined add the walnuts and cacao nibs and mix quickly.", "Drop heaping tablespoons of dough about 2½ inches (6.25cm) apart on the sheets, flatten slightly, and bake 12 minutes.", "Let the cookies sit 1 minute on the sheets, then gently press a dent in each with the handle of a wooden spoon. After another minute, widen the dent with your thumb. Move to a rack to cool.", "Put the chocolate in a small heatproof bowl.", "Heat the coffee creamer in a small saucepan on medium-high until steaming and just bubbling at the edges, without boiling. Pour over the chocolate and leave 5 minutes. Whisk smooth, whisk in the maple syrup, and let stand 5 minutes more to thicken a little.", "Spoon the ganache into each dent and let set fully before serving. Keeps 3 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-091", "Parsnip Cupcakes with Sour Cream Icing", "American", ["section-book-plant-based"], "veg", "dessert", 45, "These cupcakes are like carrot cake, but more interesting.", [I("nondairy milk, such as soy or rice", 6, "tbsp", "Pantry"), I("flax meal (ground flaxseeds)", 2, "tbsp", "Pantry"), I("all-purpose flour", 1, "cups", "Pantry"), I("baking powder", 1.5, "tsp", "Pantry"), I("kosher salt", 0.5, "tsp", "Herbs & Spices"), I("ground cinnamon", 0.5, "tsp", "Herbs & Spices"), I("ground cardamom", 0.5, "tsp", "Herbs & Spices"), I("brown sugar, lightly packed", 0.75, "cups", "Pantry"), I("grapeseed oil", 0.6667, "cups", "Pantry"), I("vanilla extract", 1, "tsp", "Herbs & Spices"), I("medium parsnips, peeled and grated (2 cups)", 2, "", "Produce"), I("currants", 0.25, "cups", "Pantry"), I("plant-based butter", 0.25, "cups", "Dairy & Eggs"), I("confectioners’ sugar, sifted twice", 1, "cups", "Pantry"), I("plant-based sour cream", 0.5, "cups", "Dairy & Eggs")], ["Heat the oven to 350°F (180°C) and put paper liners in a 12-cup muffin tin.", "Warm the nondairy milk in a small saucepan on medium just until bubbles appear at the edge.", "Pour the warm milk over the flax meal in a small bowl, stir, and leave 10 minutes.", "Whisk the all-purpose flour with the cardamom, cinnamon, kosher salt, and baking powder in a large bowl.", "In another bowl, whisk the grapeseed oil, brown sugar, vanilla extract, and flax mixture until smooth, then stir into the dry mixture just until combined.", "Fold in the parsnips and currants.", "Fill the cups a little over half full and bake 22 to 25 minutes, until the centers spring back and a toothpick comes out clean. Cool 5 minutes in the tin, then move to a rack to cool completely.", "Meanwhile, beat the butter and confectioners' sugar in a medium bowl with an electric mixer on medium until smooth, then beat in the sour cream briefly.", "Spread or dip the cooled cupcakes in the icing and serve. Un-iced cupcakes keep up to 2 days in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-092", "Winter Fruit Compote", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Fresh, seasonal apples and pears combine with dried fruits for a sweet, nourishing, fiber-rich treat.", [I("apple cider", 1, "cups", "Produce"), I("dark rum", 2, "tbsp", "Pantry"), I("vanilla bean, split lengthwise", 1, "", "Herbs & Spices"), I("(3- or 4-in.; 7.5 to 10cm) cinnamon stick", 1, "", "Herbs & Spices"), I("(2-in.; 5cm) strips lemon peel, thinly sliced", 2, "", "Produce"), I("granulated cane sugar", 0.5, "cups", "Pantry"), I("medium tart apple, such as Granny Smith, peeled, cored, and chopped", 1, "", "Produce"), I("ripe Bartlett pear, peeled, cored, and chopped", 1, "", "Produce"), I("dried apricots, roughly chopped", 0.5, "cups", "Pantry"), I("dried figs, roughly chopped", 0.5, "cups", "Pantry"), I("raisins", 0.5, "cups", "Pantry"), I("dried cranberries", 0.5, "cups", "Pantry"), I("dried tart cherries", 0.5, "cups", "Pantry")], ["Combine the apple cider and rum with the sugar, the lemon peel, the cinnamon stick, and the vanilla bean in a large lidded saucepan on high and bring to a boil, stirring often until the sugar dissolves.", "Add the apple and pear, lower the heat, cover, and cook 10 minutes.", "Uncover and add the apricots, figs, raisins, cranberries, and cherries.", "Cover again and cook 15 minutes, until all the fruit is soft.", "Let cool 1 hour so the flavors blend, then take out the vanilla bean and cinnamon stick.", "Chill in an airtight container about 2 hours before serving. Keeps 1 week in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h("plnt-093", "Cranberry Poached Pears", "American", ["section-book-plant-based"], "veg", "dessert", 45, "Sweet pears are cooked in pear nectar with dried cranberries and spices for a naturally sweetened, light, and refreshing autumn or winter dessert with a gorgeous, rosy glow.", [I("pear nectar or juice", 2, "cups", "Pantry"), I("cranberry juice", 0.25, "cups", "Produce"), I("dried cranberries", 1, "cups", "Pantry"), I("(3- or 4-in.; 7.5 to 10cm) cinnamon stick", 1, "", "Herbs & Spices"), I("cardamom pods, cracked with a heavy knife", 2, "", "Herbs & Spices"), I("star anise pod", 1, "", "Pantry"), I("medium pears", 6, "", "Produce")], ["In a saucepan just big enough for the pears, stir together the pear nectar, cranberry juice, and cranberries.", "Tie the cinnamon stick, cardamom pods, and star anise in a double layer of cheesecloth with kitchen twine. Drop the bundle into the pan and set on medium-high.", "Peel the pears, keeping the stems on, and trim a thin slice from each base so they stand up. Put them straight into the liquid. Once it boils, cover, lower the heat, and simmer gently for 30 minutes, until a fork slides in easily.", "Lift the pears into a serving dish and discard the spice bundle.", "Boil the liquid on high, stirring often, until reduced by half to about 1 cup. Pour over the pears and let cool completely.", "Serve at room temperature or chilled, one pear per plate with a few spoonfuls of sauce and cranberries. Keeps up to 7 days covered in the refrigerator."], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
];
